function(container, apiUrl, tables) {
  let loginAttempts = 0;
  const maxAttempts = 5;
  let isAccountLocked = false;

  // DOM要素の取得
  const form = container.querySelector('#login-form');
  const userIdInput = container.querySelector('#user-id');
  const passwordInput = container.querySelector('#password');
  const togglePasswordBtn = container.querySelector('#toggle-password');
  const rememberMeCheckbox = container.querySelector('#remember-me');
  const loginButton = container.querySelector('#login-button');
  const errorMessage = container.querySelector('#error-message');
  const forgotPasswordLink = container.querySelector('#forgot-password-link');

  // エラーメッセージ表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
  }

  function hideError() {
    errorMessage.style.display = 'none';
  }

  // バリデーション関数
  function validateForm() {
    const userId = userIdInput.value.trim();
    const password = passwordInput.value;

    if (!userId && !password) {
      showError('ユーザーIDとパスワードを入力してください');
      return false;
    }

    if (!userId) {
      showError('ユーザーIDを入力してください');
      return false;
    }

    if (!password) {
      showError('パスワードを入力してください');
      return false;
    }

    // 特殊文字チェック
    const dangerousChars = /<|>|script|drop|select|insert|update|delete|union|exec/i;
    if (dangerousChars.test(userId) || dangerousChars.test(password)) {
      showError('不正な文字が含まれています');
      return false;
    }

    return true;
  }

  // 認証処理
  async function authenticate(userId, password) {
    if (isAccountLocked) {
      showError('アカウントがロックされました。しばらく時間をおいてから再度お試しください。');
      return false;
    }

    try {
      // ユーザーテーブルから認証情報を取得
      const users = await window.aivicApi.list(0); // ユーザーテーブル

      if (!users) {
        showError('システムエラーが発生しました');
        return false;
      }

      // ユーザー検索（実際の実装ではパスワードハッシュ比較）
      const user = users.find(u => 
        u.ユーザー名 === userId && 
        u.有効フラグ === true
      );

      if (!user) {
        loginAttempts++;
        if (loginAttempts >= maxAttempts) {
          isAccountLocked = true;
          showError('アカウントがロックされました。しばらく時間をおいてから再度お試しください。');
        } else {
          showError('ユーザーIDまたはパスワードが正しくありません');
        }
        return false;
      }

      // 簡易パスワード検証（実際の実装ではハッシュ比較）
      if (password !== 'password123') {
        loginAttempts++;
        if (loginAttempts >= maxAttempts) {
          isAccountLocked = true;
          showError('アカウントがロックされました。しばらく時間をおいてから再度お試しください。');
        } else {
          showError('ユーザーIDまたはパスワードが正しくありません');
        }
        return false;
      }

      // ログイン成功
      loginAttempts = 0;

      // 最終ログイン日時を更新
      await window.aivicApi.update(0, user.ユーザーID, {
        最終ログイン日時: new Date().toISOString()
      });

      // ログイン状態保持
      if (rememberMeCheckbox.checked) {
        localStorage.setItem('loginUser', JSON.stringify({
          userId: user.ユーザーID,
          userName: user.ユーザー名,
          displayName: user.氏名,
          loginTime: new Date().toISOString()
        }));
      } else {
        sessionStorage.setItem('loginUser', JSON.stringify({
          userId: user.ユーザーID,
          userName: user.ユーザー名,
          displayName: user.氏名,
          loginTime: new Date().toISOString()
        }));
      }

      return true;
    } catch (error) {
      console.error('Authentication error:', error);
      showError('システムエラーが発生しました');
      return false;
    }
  }

  // パスワード表示切り替え
  togglePasswordBtn.addEventListener('click', () => {
    const isPassword = passwordInput.type === 'password';
    passwordInput.type = isPassword ? 'text' : 'password';
    togglePasswordBtn.textContent = isPassword ? '🙈' : '👁';
  });

  // フォーム送信処理
  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    hideError();

    if (!validateForm()) {
      return;
    }

    const userId = userIdInput.value.trim();
    const password = passwordInput.value;

    // ログインボタンを無効化
    loginButton.disabled = true;
    loginButton.textContent = 'ログイン中...';

    try {
      const success = await authenticate(userId, password);

      if (success) {
        // メイン画面（工数記録画面）に遷移
        window.showScreen("scr-1778907133295");
      }
    } finally {
      // ログインボタンを有効化
      loginButton.disabled = false;
      loginButton.textContent = 'ログイン';
    }
  });

  // パスワード忘れリンク
  forgotPasswordLink.addEventListener('click', (e) => {
    e.preventDefault();
    // パスワードリセット画面への遷移（実際の実装では別画面）
    alert('パスワードリセット機能は準備中です。管理者にお問い合わせください。');
  });

  // 入力時のエラーメッセージクリア
  userIdInput.addEventListener('input', hideError);
  passwordInput.addEventListener('input', hideError);

  // 既存のログイン状態チェック
  const savedLogin = localStorage.getItem('loginUser') || sessionStorage.getItem('loginUser');
  if (savedLogin) {
    try {
      const loginData = JSON.parse(savedLogin);
      // 自動ログイン（実際の実装では有効期限チェックも必要）
      window.showScreen("scr-1778907133295");
    } catch (error) {
      // 無効なデータの場合はクリア
      localStorage.removeItem('loginUser');
      sessionStorage.removeItem('loginUser');
    }
  }

  // フォーカス設定
  userIdInput.focus();
}

function(container, apiUrl, tables) {
  let currentWorkRecord = null;
  let startTime = null;
  let pauseStartTime = null;
  let totalPauseTime = 0;
  let timerInterval = null;
  let currentUser = { id: 'user-001', name: '田中 太郎', department: '設備保守部' };

  // 現在時刻の更新
  function updateCurrentTime() {
    const now = new Date();
    const timeStr = now.toLocaleString('ja-JP', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    });
    container.querySelector('#current-time').textContent = timeStr;
  }

  // 経過時間の更新
  function updateElapsedTime() {
    if (!startTime) return;

    const now = new Date();
    let elapsed = now - startTime - totalPauseTime;

    if (pauseStartTime) {
      // 中断中の場合は中断開始時点までの時間
      elapsed = pauseStartTime - startTime - totalPauseTime;
    }

    const hours = Math.floor(elapsed / (1000 * 60 * 60));
    const minutes = Math.floor((elapsed % (1000 * 60 * 60)) / (1000 * 60));
    const seconds = Math.floor((elapsed % (1000 * 60)) / 1000);

    const timeStr = `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
    container.querySelector('#elapsed-time').textContent = timeStr;
  }

  // 作業状態の更新
  function updateWorkStatus(status, color = 'rgba(128,128,128,0.2)') {
    const statusEl = container.querySelector('#work-status');
    statusEl.textContent = status;
    statusEl.style.background = color;
  }

  // ボタン状態の更新
  function updateButtonStates(isWorking, isPaused = false) {
    const startBtn = container.querySelector('#start-work-btn');
    const pauseBtn = container.querySelector('#pause-work-btn');
    const endBtn = container.querySelector('#end-work-btn');

    startBtn.disabled = isWorking;
    pauseBtn.disabled = !isWorking || isPaused;
    endBtn.disabled = !isWorking || isPaused;

    if (isPaused) {
      pauseBtn.textContent = '再開';
      pauseBtn.disabled = false;
    } else {
      pauseBtn.textContent = '中断';
    }
  }

  // 本日の作業履歴を描画
  function renderTodayHistory(records) {
    const tbody = container.querySelector('#history-tbody');
    const today = new Date().toISOString().split('T')[0];

    const todayRecords = records.filter(r => {
      if (!r.作業日) return false;
      const recordDate = new Date(r.作業日).toISOString().split('T')[0];
      return recordDate === today && r.作業員ID === currentUser.id;
    }).sort((a, b) => new Date(a.作業開始時刻) - new Date(b.作業開始時刻));

    tbody.innerHTML = todayRecords.map(r => {
      const startTime = r.作業開始時刻 ? new Date(r.作業開始時刻).toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' }) : '';
      const endTime = r.作業終了時刻 ? new Date(r.作業終了時刻).toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' }) : '';
      const workHours = r.作業時間 ? `${Math.floor(r.作業時間 / 60)}:${(r.作業時間 % 60).toString().padStart(2, '0')}` : '';

      let statusBadge = '';
      if (r.進捗状況 === '作業中') {
        statusBadge = '<span style="padding: 2px 6px; border-radius: 3px; font-size: 10px; background: rgba(34, 197, 94, 0.2); color: #22c55e;">作業中</span>';
      } else if (r.進捗状況 === '完了') {
        statusBadge = '<span style="padding: 2px 6px; border-radius: 3px; font-size: 10px; background: rgba(59, 130, 246, 0.2); color: #3b82f6;">完了</span>';
      } else if (r.進捗状況 === '中断') {
        statusBadge = '<span style="padding: 2px 6px; border-radius: 3px; font-size: 10px; background: rgba(245, 158, 11, 0.2); color: #f59e0b;">中断</span>';
      }

      return `
        <tr data-id="${r.id}">
          <td style="padding: 6px 10px; font-size: 13px;">${startTime}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${endTime}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${r.作業種別 || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${r.作業場所 || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${workHours}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${statusBadge}</td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <button class="action-btn secondary edit-btn" data-id="${r.id}" style="font-size: 11px; padding: 4px 8px;">編集</button>
            <button class="action-btn secondary delete-btn" data-id="${r.id}" style="font-size: 11px; padding: 4px 8px;">削除</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 作業項目の読み込み
  async function loadWorkItems() {
    const workItems = await window.aivicApi.list(3); // 作業項目マスタ
    const select = container.querySelector('#work-item-select');

    if (workItems) {
      select.innerHTML = '<option value="">選択してください</option>' + 
        workItems.filter(item => item.有効フラグ)
          .sort((a, b) => (a.表示順序 || 0) - (b.表示順序 || 0))
          .map(item => `<option value="${item.id}">${item.作業項目名}</option>`)
          .join('');
    }
  }

  // 初期データの読み込みと描画
  async function loadInitialData() {
    const workRecords = await window.aivicApi.list(1); // 作業記録
    if (workRecords) {
      renderTodayHistory(workRecords);
    }
    await loadWorkItems();
  }

  // 文字数カウンターの更新
  function updateCharCount(textarea, countElement) {
    const count = textarea.value.length;
    countElement.textContent = count;
    if (count >= textarea.maxLength * 0.9) {
      countElement.style.color = '#ef4444';
    } else {
      countElement.style.color = 'var(--text-muted)';
    }
  }

  // 作業開始
  async function startWork() {
    const workItemId = container.querySelector('#work-item-select').value;
    const workLocation = container.querySelector('#work-location-input').value.trim();
    const workContent = container.querySelector('#work-content-textarea').value.trim();

    if (!workItemId) {
      alert('作業項目を選択してください');
      return;
    }

    if (!workLocation) {
      alert('作業場所を入力してください');
      return;
    }

    if (!workContent) {
      alert('作業内容を入力してください');
      return;
    }

    const workItems = await window.aivicApi.list(3);
    const selectedItem = workItems?.find(item => item.id === workItemId);

    const now = new Date();
    const workRecord = {
      作業員ID: currentUser.id,
      作業日: now,
      作業開始時刻: now,
      プロジェクト名: selectedItem?.作業項目名|| '',
      作業場所: workLocation,
      作業種別: selectedItem?.作業項目名|| '',
      作業内容: workContent,
      進捗状況: '作業中',
      承認状態: '未承認',
      作成者ID: currentUser.id
    };

    const saved = await window.aivicApi.save(1, workRecord);
    if (saved) {
      currentWorkRecord = saved;
      startTime = now;
      pauseStartTime = null;
      totalPauseTime = 0;

      updateWorkStatus('作業中', 'rgba(34, 197, 94, 0.2)');
      updateButtonStates(true, false);

      // タイマー開始
      timerInterval = setInterval(updateElapsedTime, 1000);

      // 履歴を再読み込み
      loadInitialData();
    }
  }

  // 作業中断
  function pauseWork() {
    if (!currentWorkRecord) {
      alert('作業が開始されていません');
      return;
    }

    if (pauseStartTime) {
      // 再開処理
      const now = new Date();
      totalPauseTime += now - pauseStartTime;
      pauseStartTime = null;

      updateWorkStatus('作業中', 'rgba(34, 197, 94, 0.2)');
      updateButtonStates(true, false);
    } else {
      // 中断処理 - モーダル表示
      container.querySelector('#pause-modal').classList.remove('hidden');
    }
  }

  // 作業終了
  async function endWork() {
    if (!currentWorkRecord) {
      alert('作業が開始されていません');
      return;
    }

    const now = new Date();
    let workTime = Math.floor((now - startTime - totalPauseTime) / (1000 * 60)); // 分単位

    if (pauseStartTime) {
      // 中断中の場合は中断開始時点までの時間
      workTime = Math.floor((pauseStartTime - startTime - totalPauseTime) / (1000 * 60));
    }

    const updated = await window.aivicApi.update(1, currentWorkRecord.id, {
      作業終了時刻: now,
      作業時間: workTime,
      進捗状況: '完了'
    });

    if (updated) {
      currentWorkRecord = null;
      startTime = null;
      pauseStartTime = null;
      totalPauseTime = 0;

      if (timerInterval) {
        clearInterval(timerInterval);
        timerInterval = null;
      }

      updateWorkStatus('待機中', 'rgba(128,128,128,0.2)');
      updateButtonStates(false, false);
      container.querySelector('#elapsed-time').textContent = '00:00:00';

      // フォームクリア
      container.querySelector('#work-item-select').value = '';
      container.querySelector('#work-location-input').value = '';
      container.querySelector('#work-content-textarea').value = '';
      container.querySelector('#work-memo-textarea').value = '';
      updateCharCount(container.querySelector('#work-memo-textarea'), container.querySelector('#memo-count'));

      // 履歴を再読み込み
      loadInitialData();
    }
  }

  // 保存処理
  async function saveWork() {
    const workMemo = container.querySelector('#work-memo-textarea').value.trim();

    if (currentWorkRecord && workMemo) {
      await window.aivicApi.update(1, currentWorkRecord.id, {
        備考: workMemo
      });
    }

    alert('保存しました');
  }

  // キャンセル処理
  function cancelWork() {
    if (currentWorkRecord) {
      if (!confirm('作業中です。キャンセルしますか？')) {
        return;
      }

      // 作業中の記録を削除
      window.aivicApi.delete(1, currentWorkRecord.id);

      currentWorkRecord = null;
      startTime = null;
      pauseStartTime = null;
      totalPauseTime = 0;

      if (timerInterval) {
        clearInterval(timerInterval);
        timerInterval = null;
      }

      updateWorkStatus('待機中', 'rgba(128,128,128,0.2)');
      updateButtonStates(false, false);
      container.querySelector('#elapsed-time').textContent = '00:00:00';
    }

    // フォームクリア
    container.querySelector('#work-item-select').value = '';
    container.querySelector('#work-location-input').value = '';
    container.querySelector('#work-content-textarea').value = '';
    container.querySelector('#work-memo-textarea').value = '';
    updateCharCount(container.querySelector('#work-memo-textarea'), container.querySelector('#memo-count'));

    loadInitialData();
  }

  // 中断確定処理
  async function confirmPause() {
    const category = container.querySelector('#pause-reason-category').value;
    const detail = container.querySelector('#pause-reason-detail').value.trim();

    if (!category) {
      alert('中断理由を選択してください');
      return;
    }

    if (!detail) {
      alert('中断理由の詳細を入力してください');
      return;
    }

    const now = new Date();
    pauseStartTime = now;

    // 中断記録を保存
    const pauseRecord = {
      作業記録ID: currentWorkRecord.id,
      中断開始日時: now,
      中断理由区分: category,
      中断理由詳細: detail,
      対応状況: '対応中',
      記録者ID: currentUser.id
    };

    await window.aivicApi.save(2, pauseRecord);

    updateWorkStatus('中断中', 'rgba(245, 158, 11, 0.2)');
    updateButtonStates(true, true);

    // モーダルを閉じる
    container.querySelector('#pause-modal').classList.add('hidden');
    container.querySelector('#pause-reason-category').value = '';
    container.querySelector('#pause-reason-detail').value = '';
    updateCharCount(container.querySelector('#pause-reason-detail'), container.querySelector('#pause-reason-count'));
  }

  // イベントリスナーの設定
  container.querySelector('#start-work-btn').addEventListener('click', startWork);
  container.querySelector('#pause-work-btn').addEventListener('click', pauseWork);
  container.querySelector('#end-work-btn').addEventListener('click', endWork);
  container.querySelector('#save-btn').addEventListener('click', saveWork);
  container.querySelector('#cancel-btn').addEventListener('click', cancelWork);

  // 中断モーダル関連
  container.querySelector('#pause-confirm-btn').addEventListener('click', confirmPause);
  container.querySelector('#pause-cancel-btn').addEventListener('click', () => {
    container.querySelector('#pause-modal').classList.add('hidden');
  });

  // 文字数カウンター
  container.querySelector('#work-memo-textarea').addEventListener('input', (e) => {
    updateCharCount(e.target, container.querySelector('#memo-count'));
  });

  container.querySelector('#pause-reason-detail').addEventListener('input', (e) => {
    updateCharCount(e.target, container.querySelector('#pause-reason-count'));
  });

  // 行レベル操作（編集・削除）
  container.addEventListener('click', async (e) => {
    const deleteBtn = e.target.closest('.delete-btn');
    const editBtn = e.target.closest('.edit-btn');

    if (deleteBtn) {
      if (!confirm('この作業記録を削除しますか？')) return;

      await window.aivicApi.delete(1, deleteBtn.dataset.id);
      loadInitialData();
    }

    if (editBtn) {
      // 編集機能は別画面で実装されると想定
      alert('編集機能は作業履歴画面で実装されます');
    }
  });

  // 初期化
  updateCurrentTime();
  setInterval(updateCurrentTime, 1000);
  updateWorkStatus('待機中');
  updateButtonStates(false, false);
  loadInitialData();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#work-history-tbody");
  const noResults = container.querySelector("#no-results");
  const errorMessage = container.querySelector("#error-message");

  let allWorkRecords = [];
  let allBreakRecords = [];
  let allWorkItems = [];

  // エラー表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = "block";
    setTimeout(() => {
      errorMessage.style.display = "none";
    }, 5000);
  }

  // 中断回数を計算する関数
  function getBreakCount(workRecordId) {
    return allBreakRecords.filter(br => br.作業記録ID === workRecordId).length;
  }

  // 作業時間をフォーマットする関数
  function formatWorkTime(minutes) {
    if (!minutes) return "-";
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return `${hours}時間${mins}分`;
  }

  // 日付をフォーマットする関数
  function formatDate(dateStr) {
    if (!dateStr) return "-";
    const date = new Date(dateStr);
    return date.toLocaleDateString('ja-JP');
  }

  // 時刻をフォーマットする関数
  function formatTime(dateStr) {
    if (!dateStr) return "-";
    const date = new Date(dateStr);
    return date.toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
  }

  // 作業項目名を取得する関数
  function getWorkItemName(workContent) {
    const workItem = allWorkItems.find(item => item.作業項目名 === workContent);
    return workItem ? workItem.作業項目名 : workContent || "-";
  }

  // ステータスバッジのスタイルを取得
  function getStatusBadgeStyle(status) {
    switch(status) {
      case "完了":
        return "background: rgba(34, 197, 94, 0.2); color: #22c55e; padding: 2px 8px; border-radius: 4px; font-size: 11px; font-weight: 500;";
      case "作業中":
        return "background: rgba(59, 130, 246, 0.2); color: #3b82f6; padding: 2px 8px; border-radius: 4px; font-size: 11px; font-weight: 500;";
      case "中断":
        return "background: rgba(245, 158, 11, 0.2); color: #f59e0b; padding: 2px 8px; border-radius: 4px; font-size: 11px; font-weight: 500;";
      default:
        return "background: rgba(107, 114, 128, 0.2); color: #6b7280; padding: 2px 8px; border-radius: 4px; font-size: 11px; font-weight: 500;";
    }
  }

  // テーブル再描画関数
  function renderRows(rows) {
    if (rows.length === 0) {
      tbody.innerHTML = "";
      noResults.style.display = "block";
      return;
    }

    noResults.style.display = "none";
    tbody.innerHTML = rows.map(r => {
      const breakCount = getBreakCount(r.作業記録ID);
      const workItemName = getWorkItemName(r.作業内容);

      return `
        <tr data-id="${r.作業記録ID}" style="border-bottom: 1px solid var(--border);">
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatDate(r.作業日)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${workItemName}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatTime(r.作業開始時刻)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatTime(r.作業終了時刻)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatWorkTime(r.作業時間)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); text-align: center;">${breakCount}</td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <span style="${getStatusBadgeStyle(r.進捗状況)}">${r.進捗状況 || "-"}</span>
          </td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <button class="action-btn secondary detail-btn" data-id="${r.作業記録ID}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer; margin-right: 4px;">詳細確認</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 作業項目ドロップダウンを更新
  function updateWorkItemFilter() {
    const workItemFilter = container.querySelector("#filter-work-item");
    const uniqueWorkItems = [...new Set(allWorkRecords.map(r => getWorkItemName(r.作業内容)))];

    workItemFilter.innerHTML = '<option value="">すべて</option>' + 
      uniqueWorkItems.map(item => `<option value="${item}">${item}</option>`).join("");
  }

  // フィルター処理
  function applyFilters() {
    const startDate = container.querySelector("#filter-start-date").value;
    const endDate = container.querySelector("#filter-end-date").value;
    const workItem = container.querySelector("#filter-work-item").value;
    const status = container.querySelector("#filter-status").value;

    // バリデーション
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      showError("開始日は終了日より前の日付を入力してください");
      return;
    }

    const today = new Date();
    today.setHours(23, 59, 59, 999);

    if (startDate && new Date(startDate) > today) {
      showError("未来の日付は選択できません");
      return;
    }

    if (endDate && new Date(endDate) > today) {
      showError("未来の日付は選択できません");
      return;
    }

    if (startDate && endDate) {
      const start = new Date(startDate);
      const end = new Date(endDate);
      const diffTime = Math.abs(end - start);
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

      if (diffDays > 365) {
        showError("1年以上の期間は選択できません");
        return;
      }
    }

    let filteredRows = allWorkRecords.filter(row => {
      // 日付フィルター
      if (startDate || endDate) {
        const workDate = new Date(row.作業日);
        if (startDate && workDate < new Date(startDate)) return false;
        if (endDate && workDate > new Date(endDate)) return false;
      }

      // 作業項目フィルター
      if (workItem && getWorkItemName(row.作業内容) !== workItem) return false;

      // ステータスフィルター
      if (status && row.進捗状況 !== status) return false;

      return true;
    });

    renderRows(filteredRows);
  }

  // CSVエクスポート
  function exportCSV() {
    window.aivicApi.list(1).then(rows => {
      if (!rows || rows.length === 0) {
        showError("エクスポートするデータがありません");
        return;
      }

      const headers = ["作業日時", "作業項目名", "開始時刻", "終了時刻", "作業時間", "中断回数", "状況", "作業内容", "作業場所"];
      const csvContent = "\uFEFF" + [
        headers.join(","),
        ...rows.map(row => {
          const breakCount = getBreakCount(row.作業記録ID);
          const workItemName = getWorkItemName(row.作業内容);

          return [
            `"${formatDate(row.作業日)}"`,
            `"${workItemName}"`,
            `"${formatTime(row.作業開始時刻)}"`,
            `"${formatTime(row.作業終了時刻)}"`,
            `"${formatWorkTime(row.作業時間)}"`,
            breakCount,
            `"${row.進捗状況 || ""}"`,
            `"${(row.作業内容 || "").replace(/"/g, '""')}"`,
            `"${(row.作業場所 || "").replace(/"/g, '""')}"`
          ].join(",");
        })
      ].join("\n");

      const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = `作業履歴_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    });
  }

  // 初期データ読み込み
  Promise.all([
    window.aivicApi.list(1), // 作業記録
    window.aivicApi.list(2), // 中断記録
    window.aivicApi.list(3)  // 作業項目マスタ
  ]).then(([workRecords, breakRecords, workItems]) => {
    allWorkRecords = workRecords || tables[1]?.records || [];
    allBreakRecords = breakRecords || tables[2]?.records || [];
    allWorkItems = workItems || tables[3]?.records || [];

    updateWorkItemFilter();
    renderRows(allWorkRecords);
  });

  // 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", applyFilters);

  // リセットボタン
  container.querySelector("#btn-reset").addEventListener("click", () => {
    container.querySelector("#filter-start-date").value = "";
    container.querySelector("#filter-end-date").value = "";
    container.querySelector("#filter-work-item").value = "";
    container.querySelector("#filter-status").value = "";
    renderRows(allWorkRecords);
  });

  // CSVエクスポートボタン
  container.querySelector("#btn-csv-export").addEventListener("click", exportCSV);

  // データ抽出ボタン
  container.querySelector("#btn-data-extract").addEventListener("click", () => {
    window.showScreen("scr-1778907353387");
  });

  // 戻るボタン
  container.querySelector("#btn-back").addEventListener("click", () => {
    window.showScreen("scr-1778907133295");
  });

  // 行レベル操作（詳細確認）
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const recordId = detailBtn.dataset.id;
      // 詳細確認画面に遷移（レコードIDを渡す方法は実装依存）
      window.showScreen("scr-1778907367889");
    }
  });
}

function(container, apiUrl, tables) {
  let currentData = [];
  let currentPage = 1;
  const itemsPerPage = 20;
  let selectedLogId = null;

  // テーブル再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector("#anomaly-log-tbody");
    const resultCount = container.querySelector("#result-count");

    currentData = rows;
    resultCount.textContent = `検索結果: ${rows.length}件`;

    // ページネーション計算
    const totalPages = Math.ceil(rows.length / itemsPerPage);
    const startIndex = (currentPage - 1) * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;
    const pageRows = rows.slice(startIndex, endIndex);

    tbody.innerHTML = pageRows.map(r => {
      const detectionDate = r.検出日時 ? new Date(r.検出日時).toLocaleString('ja-JP') : '';
      const statusBadge = getStatusBadge(r.確認状況 || '未確認');
      const severityBadge = getSeverityBadge(r.重要度 || '中');

      return `
        <tr data-id="${r.異常値検出ログID || r.id}" style="height: 36px;">
          <td style="padding: 6px 10px; font-size: 13px;">${detectionDate}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${r.作業員名 || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${r.異常値種別 || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${r.検出項目 || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${r.検出値 || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${r.閾値 || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${severityBadge}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${statusBadge}</td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <button class="action-btn secondary detail-btn" data-id="${r.異常値検出ログID || r.id}" style="font-size: 12px; padding: 4px 8px;">詳細</button>
          </td>
        </tr>
      `;
    }).join("");

    renderPagination(totalPages);
  }

  // ステータスバッジ
  function getStatusBadge(status) {
    const colors = {
      '未確認': 'background: rgba(255, 107, 107, 0.2); color: #ff6b6b; border: 1px solid rgba(255, 107, 107, 0.3);',
      '確認済み': 'background: rgba(255, 193, 7, 0.2); color: #ffc107; border: 1px solid rgba(255, 193, 7, 0.3);',
      '対応済み': 'background: rgba(40, 167, 69, 0.2); color: #28a745; border: 1px solid rgba(40, 167, 69, 0.3);'
    };
    return `<span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500; ${colors[status] || colors['未確認']}">${status}</span>`;
  }

  // 重要度バッジ
  function getSeverityBadge(severity) {
    const colors = {
      '高': 'background: rgba(220, 53, 69, 0.2); color: #dc3545; border: 1px solid rgba(220, 53, 69, 0.3);',
      '中': 'background: rgba(255, 193, 7, 0.2); color: #ffc107; border: 1px solid rgba(255, 193, 7, 0.3);',
      '低': 'background: rgba(108, 117, 125, 0.2); color: #6c757d; border: 1px solid rgba(108, 117, 125, 0.3);'
    };
    return `<span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500; ${colors[severity] || colors['中']}">${severity}</span>`;
  }

  // ページネーション描画
  function renderPagination(totalPages) {
    const pagination = container.querySelector("#pagination");
    if (totalPages <= 1) {
      pagination.innerHTML = "";
      return;
    }

    let paginationHtml = "";

    // 前へボタン
    if (currentPage > 1) {
      paginationHtml += `<button class="action-btn secondary" data-page="${currentPage - 1}">前へ</button>`;
    }

    // ページ番号
    const startPage = Math.max(1, currentPage - 2);
    const endPage = Math.min(totalPages, currentPage + 2);

    for (let i = startPage; i <= endPage; i++) {
      const isActive = i === currentPage;
      paginationHtml += `<button class="action-btn ${isActive ? '' : 'secondary'}" data-page="${i}" ${isActive ? 'disabled' : ''}>${i}</button>`;
    }

    // 次へボタン
    if (currentPage < totalPages) {
      paginationHtml += `<button class="action-btn secondary" data-page="${currentPage + 1}">次へ</button>`;
    }

    pagination.innerHTML = paginationHtml;
  }

  // フィルター適用
  function applyFilters() {
    const startDate = container.querySelector("#filter-start-date").value;
    const endDate = container.querySelector("#filter-end-date").value;
    const anomalyType = container.querySelector("#filter-anomaly-type").value;
    const workerName = container.querySelector("#filter-worker-name").value;
    const workItem = container.querySelector("#filter-work-item").value;
    const status = container.querySelector("#filter-status").value;

    window.aivicApi.list(4).then(rows => {
      if (!rows) return;

      let filtered = rows.filter(r => {
        // 日付フィルター
        if (startDate && r.検出日時) {
          const detectionDate = new Date(r.検出日時);
          const filterStartDate = new Date(startDate);
          if (detectionDate < filterStartDate) return false;
        }
        if (endDate && r.検出日時) {
          const detectionDate = new Date(r.検出日時);
          const filterEndDate = new Date(endDate);
          if (detectionDate > filterEndDate) return false;
        }

        // 異常値タイプフィルター
        if (anomalyType && r.異常値種別 !== anomalyType) return false;

        // 作業員名検索
        if (workerName && (!r.作業員名 || !r.作業員名.includes(workerName))) return false;

        // 作業項目フィルター
        if (workItem && r.作業項目 !== workItem) return false;

        // ステータスフィルター
        if (status && r.確認状況 !== status) return false;

        return true;
      });

      currentPage = 1;
      renderRows(filtered);
    });
  }

  // フィルタークリア
  function clearFilters() {
    container.querySelector("#filter-start-date").value = "";
    container.querySelector("#filter-end-date").value = "";
    container.querySelector("#filter-anomaly-type").value = "";
    container.querySelector("#filter-worker-name").value = "";
    container.querySelector("#filter-work-item").value = "";
    container.querySelector("#filter-status").value = "";

    currentPage = 1;
    window.aivicApi.list(4).then(renderRows);
  }

  // 詳細表示
  function showDetail(logId) {
    window.aivicApi.list(4).then(rows => {
      if (!rows) return;

      const log = rows.find(r => (r.異常値検出ログID || r.id) === logId);
      if (!log) return;

      selectedLogId = logId;
      const modal = container.querySelector("#detail-modal");
      const content = container.querySelector("#detail-content");
      const statusSelect = container.querySelector("#status-update");
      const memoTextarea = container.querySelector("#response-memo");

      const detectionDate = log.検出日時 ? new Date(log.検出日時).toLocaleString('ja-JP') : '';

      content.innerHTML = `
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px; font-size: 13px;">
          <div><strong>検出日時:</strong> ${detectionDate}</div>
          <div><strong>作業員名:</strong> ${log.作業員名 || ''}</div>
          <div><strong>異常値種別:</strong> ${log.異常値種別 || ''}</div>
          <div><strong>検出項目:</strong> ${log.検出項目 || ''}</div>
          <div><strong>検出値:</strong> ${log.検出値 || ''}</div>
          <div><strong>閾値:</strong> ${log.閾値 || ''}</div>
          <div><strong>重要度:</strong> ${log.重要度 || ''}</div>
          <div><strong>対象テーブル:</strong> ${log.検出対象テーブル || ''}</div>
        </div>
        ${log.対応メモ ? `<div style="margin-top: 12px; padding: 8px; background: var(--bg-main); border-radius: 6px; font-size: 13px;"><strong>既存メモ:</strong><br>${log.対応メモ}</div>` : ''}
      `;

      statusSelect.value = log.確認状況 || '未確認';
      memoTextarea.value = log.対応メモ || '';
      updateMemoCount();

      modal.classList.remove("hidden");
    });
  }

  // メモ文字数カウント更新
  function updateMemoCount() {
    const memo = container.querySelector("#response-memo");
    const count = container.querySelector("#memo-count");
    count.textContent = memo.value.length;
  }

  // ステータス更新
  function updateStatus() {
    if (!selectedLogId) return;

    const status = container.querySelector("#status-update").value;
    const memo = container.querySelector("#response-memo").value;

    if (memo.length > 1000) {
      alert("コメントは1000文字以内で入力してください");
      return;
    }

    const updateData = {
      確認状況: status,
      対応メモ: memo,
      確認日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };

    window.aivicApi.update(4, selectedLogId, updateData).then(result => {
      if (result) {
        alert("更新しました");
        container.querySelector("#detail-modal").classList.add("hidden");
        applyFilters(); // 現在のフィルター条件で再検索
      } else {
        alert("更新に失敗しました");
      }
    });
  }

  // CSVエクスポート
  function exportCSV() {
    window.aivicApi.list(4).then(rows => {
      if (!rows || rows.length === 0) {
        alert("エクスポートするデータがありません");
        return;
      }

      const headers = ["検出日時", "作業員名", "異常値種別", "検出項目", "検出値", "閾値", "重要度", "確認状況", "対応メモ"];
      const csvData = [headers.join(",")];

      rows.forEach(r => {
        const row = [
          r.検出日時 ? new Date(r.検出日時).toLocaleString('ja-JP') : '',
          r.作業員名 || '',
          r.異常値種別 || '',
          r.検出項目 || '',
          r.検出値 || '',
          r.閾値 || '',
          r.重要度 || '',
          r.確認状況 || '',
          (r.対応メモ || '').replace(/"/g, '""')
        ].map(field => `"${field}"`);
        csvData.push(row.join(","));
      });

      const blob = new Blob(["\uFEFF" + csvData.join("\n")], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = `異常値検出ログ_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    });
  }

  // 初期データ読み込み
  window.aivicApi.list(4).then(renderRows);

  // イベントリスナー
  container.querySelector("#btn-search").addEventListener("click", applyFilters);
  container.querySelector("#btn-clear-filter").addEventListener("click", clearFilters);
  container.querySelector("#btn-export").addEventListener("click", exportCSV);

  // モーダル関連
  container.querySelector("#btn-close-modal").addEventListener("click", () => {
    container.querySelector("#detail-modal").classList.add("hidden");
  });
  container.querySelector("#btn-cancel-update").addEventListener("click", () => {
    container.querySelector("#detail-modal").classList.add("hidden");
  });
  container.querySelector("#btn-update-status").addEventListener("click", updateStatus);

  // メモ文字数カウント
  container.querySelector("#response-memo").addEventListener("input", updateMemoCount);

  // イベントデリゲーション
  container.addEventListener("click", e => {
    // 詳細ボタン
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      showDetail(detailBtn.dataset.id);
      return;
    }

    // ページネーション
    const pageBtn = e.target.closest("[data-page]");
    if (pageBtn && !pageBtn.disabled) {
      currentPage = parseInt(pageBtn.dataset.page);
      renderRows(currentData);
      return;
    }

    // モーダル背景クリック
    if (e.target.id === "detail-modal") {
      container.querySelector("#detail-modal").classList.add("hidden");
    }
  });
}

function(container, apiUrl, tables) {
  let currentResumeWorkId = null;
  let activeWorksData = [];
  let suspendedWorksData = [];
  let workItemsData = [];

  // 現在時刻更新
  function updateCurrentTime() {
    const now = new Date();
    const timeStr = now.getFullYear() + '/' + 
                   String(now.getMonth() + 1).padStart(2, '0') + '/' + 
                   String(now.getDate()).padStart(2, '0') + ' ' + 
                   String(now.getHours()).padStart(2, '0') + ':' + 
                   String(now.getMinutes()).padStart(2, '0');
    container.querySelector('#current-datetime').textContent = timeStr;
  }

  // 作業項目選択肢を描画
  function renderWorkItems(items) {
    const select = container.querySelector('#work-item-select');
    select.innerHTML = '<option value="">作業項目を選択してください</option>';
    items.filter(item => item.有効フラグ).forEach(item => {
      select.innerHTML += `<option value="${item.作業項目ID}">${item.作業項目名}</option>`;
    });
  }

  // 進行中作業一覧を描画
  function renderActiveWorks(works) {
    const listEl = container.querySelector('#active-works-list');
    if (!works || works.length === 0) {
      listEl.innerHTML = '<div style="color: var(--text-muted); font-size: 12px; text-align: center; padding: 20px;">進行中の作業はありません</div>';
      return;
    }

    listEl.innerHTML = works.map(work => {
      const startTime = new Date(work.作業開始時刻);
      const elapsed = Math.floor((Date.now() - startTime.getTime()) / (1000 * 60));
      const elapsedStr = Math.floor(elapsed / 60) + '時間' + (elapsed % 60) + '分';

      return `
        <div style="border: 1px solid rgba(255,255,255,0.1); border-radius: 4px; padding: 8px; margin-bottom: 6px;">
          <div style="font-size: 13px; font-weight: 500; color: var(--text); margin-bottom: 2px;">${work.作業内容 || '作業項目不明'}</div>
          <div style="font-size: 11px; color: var(--text-muted);">開始: ${startTime.getHours()}:${String(startTime.getMinutes()).padStart(2, '0')} | 経過: ${elapsedStr}</div>
          ${work.作業場所 ? `<div style="font-size: 11px; color: var(--text-muted);">場所: ${work.作業場所}</div>` : ''}
        </div>
      `;
    }).join('');
