      listEl.innerHTML = '<div style="color: var(--text-muted); font-size: 12px; text-align: center; padding: 20px;">中断中の作業はありません</div>';
      return;
    }

    listEl.innerHTML = works.map(work => {
      const startTime = new Date(work.作業開始時刻);

      return `
        <div style="border: 1px solid rgba(255,255,255,0.1); border-radius: 4px; padding: 8px; margin-bottom: 6px;">
          <div style="display: flex; justify-content: space-between; align-items: flex-start;">
            <div style="flex: 1;">
              <div style="font-size: 13px; font-weight: 500; color: var(--text); margin-bottom: 2px;">${work.作業内容 || '作業項目不明'}</div>
              <div style="font-size: 11px; color: var(--text-muted);">開始: ${startTime.getHours()}:${String(startTime.getMinutes()).padStart(2, '0')}</div>
              ${work.作業場所 ? `<div style="font-size: 11px; color: var(--text-muted);">場所: ${work.作業場所}</div>` : ''}
            </div>
            <button class="action-btn resume-btn" data-testid="resume-work-button" data-id="${work.作業記録ID}" style="background: var(--primary); color: #fff; padding: 4px 8px; font-size: 11px; margin-left: 8px;">再開</button>
          </div>
        </div>
