      const workItems = await window.aivicApi.list(3);
      if (workItems) {
        workItemsData = workItems;
        renderWorkItems(workItems);
      }

      // 作業記録読み込み
      const workRecords = await window.aivicApi.list(1);
      if (workRecords) {
        // 進行中作業（作業終了時刻がnullで進捗状況が作業中）
        activeWorksData = workRecords.filter(record => 
          !record.作業終了時刻 && record.進捗状況 === '作業中'
        );

        // 中断中作業（進捗状況が中断）
        suspendedWorksData = workRecords.filter(record => 
          record.進捗状況 === '中断'
        );

        renderActiveWorks(activeWorksData);
        renderSuspendedWorks(suspendedWorksData);
      }
    } catch (error) {
      console.error('データ読み込みエラー:', error);
    }
  }

  // 備考文字数カウンター
  const notesInput = container.querySelector('#work-notes-input');
  const notesCounter = container.querySelector('#notes-counter');
  notesInput.addEventListener('input', () => {
    notesCounter.textContent = notesInput.value.length;
  });

  // 作業開始ボタン
  container.querySelector('#btn-start-work').addEventListener('click', async () => {
    const workItemId = container.querySelector('#work-item-select').value;
    const workLocation = container.querySelector('#work-location-input').value.trim();
    const notes = container.querySelector('#work-notes-input').value.trim();

    // バリデーション
    if (!workItemId) {
      showError('作業項目を選択してください');
      return;
    }

    // 複数作業同時開始チェック
    if (activeWorksData.length > 0) {
      showError('既に実行中の作業があります。同時に複数の作業を開始することはできません。');
      return;
    }

    // 作業場所の文字数チェック
    if (workLocation.length > 100) {
      showError('作業場所は100文字以内で入力してください');
      return;
    }

    // 備考の文字数チェック
    if (notes.length > 500) {
      showError('備考は500文字以内で入力してください');
      return;
    }

    // 不正文字チェック（簡易的なXSS対策）
    if (workLocation.includes('<script>') || workLocation.includes('</script>')) {
      showError('作業場所に不正な文字が含まれています');
      return;
    }

    try {
      const workItem = workItemsData.find(item => item.作業項目ID === workItemId);
      const now = new Date();

      const newRecord = {
        作業員ID: 'current-user-id', // 実際の実装では認証情報から取得
        作業日: now.toISOString().split('T')[0],
        作業開始時刻: now.toISOString(),
        作業終了時刻: null,
        作業時間: null,
        プロジェクト名: workItem?.作業項目名|| '',
        作業場所: workLocation,
        作業種別: workItem?.カテゴリ || '',
        作業内容: workItem?.作業項目名|| '',
        進捗状況: '作業中',
        備考: notes,
        承認状態: '未承認',
        承認者ID: null,
        承認日時: null,
        作成者ID: 'current-user-id'
      };

      const saved = await window.aivicApi.save(1, newRecord);
      if (saved) {
        // フォームクリア
        container.querySelector('#work-item-select').value = '';
        container.querySelector('#work-location-input').value = '';
        container.querySelector('#work-notes-input').value = '';
        notesCounter.textContent = '0';

        // 工数入力画面に遷移
        window.showScreen("scr-1778907296658");
      }
    } catch (error) {
      showError('作業開始に失敗しました');
      console.error('作業開始エラー:', error);
    }
  });

  // 再開ボタンのイベントデリゲーション
  container.addEventListener('click', (e) => {
    const resumeBtn = e.target.closest('.resume-btn');
    if (resumeBtn) {
      const workId = resumeBtn.dataset.id;
      const work = suspendedWorksData.find(w => w.作業記録ID === workId);

      if (!work) {
        showError('指定された作業が見つかりません');
        return;
      }

      currentResumeWorkId = workId;
      container.querySelector('#resume-dialog-message').textContent = `「${work.作業内容}」を再開しますか？`;
      container.querySelector('#resume-dialog').classList.remove('hidden');
    }
  });

  // 再開確認ダイアログ
  container.querySelector('#resume-confirm-btn').addEventListener('click', async () => {
    if (!currentResumeWorkId) return;

    try {
      const updated = await window.aivicApi.update(1, currentResumeWorkId, {
        進捗状況: '作業中',
        更新日時: new Date().toISOString()
      });

      if (updated) {
        container.querySelector('#resume-dialog').classList.add('hidden');
        currentResumeWorkId = null;
        await loadData(); // データ再読み込み
      }
    } catch (error) {
      showError('作業再開に失敗しました');
      console.error('作業再開エラー:', error);
    }
  });

  container.querySelector('#resume-cancel-btn').addEventListener('click', () => {
    container.querySelector('#resume-dialog').classList.add('hidden');
    currentResumeWorkId = null;
  });

  // 設定ボタン
  container.querySelector('#btn-settings').addEventListener('click', () => {
    // 設定画面への遷移（実装時に適切な画面IDに変更）
    alert('設定画面は未実装です');
  });

  // ログアウトボタン
  container.querySelector('#btn-logout').addEventListener('click', () => {
    if (confirm('ログアウトしますか？')) {
      window.location.href = './login.html';
    }
  });

  // 初期化
  updateCurrentTime();
  setInterval(updateCurrentTime, 60000); // 1分ごとに時刻更新
  loadData();

  // 初期データがある場合は即座に描画
  if (tables[3] && tables[3].records) {
    workItemsData = tables[3].records;
    renderWorkItems(tables[3].records);
  }

  if (tables[1] && tables[1].records) {
    const records = tables[1].records;
    activeWorksData = records.filter(record => 
      !record.作業終了時刻 && record.進捗状況 === '作業中'
    );
    suspendedWorksData = records.filter(record => 
      record.進捗状況 === '中断'
    );
    renderActiveWorks(activeWorksData);
    renderSuspendedWorks(suspendedWorksData);
  }
}

function(container, apiUrl, tables) {
  // DOM要素の取得
  const completionStatus = container.querySelector('#completion-status');
  const workMemo = container.querySelector('#work-memo');
  const hasIssue = container.querySelector('#has-issue');
  const issueContentSection = container.querySelector('#issue-content-section');
  const issueContent = container.querySelector('#issue-content');
  const errorMessage = container.querySelector('#error-message');
  const memoCount = container.querySelector('#memo-count');
  const issueCount = container.querySelector('#issue-count');
  const btnCancel = container.querySelector('#btn-cancel');
  const btnConfirm = container.querySelector('#btn-confirm');
  const btnRecordCheck = container.querySelector('#btn-record-check');

  // 現在の作業記録データ（実際の実装では前画面から受け取る）
  let currentWorkRecord = {
    id: 'work-001',
    startTime: '09:00',
    endTime: '17:30',
    totalTime: '8:30',
    breakTime: '1:00',
    actualWorkTime: '7:30',
    workItemName: 'システム開発作業'
  };

  // エラーメッセージ表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
    setTimeout(() => {
      errorMessage.style.display = 'none';
    }, 5000);
  }

  // 文字数カウント更新
  function updateMemoCount() {
    memoCount.textContent = workMemo.value.length;
  }

  function updateIssueCount() {
    issueCount.textContent = issueContent.value.length;
  }

  // 異常報告チェックボックスの制御
  hasIssue.addEventListener('change', function() {
    if (this.checked) {
      issueContentSection.style.display = 'block';
    } else {
      issueContentSection.style.display = 'none';
      issueContent.value = '';
      updateIssueCount();
    }
  });

  // 文字数カウントのイベントリスナー
  workMemo.addEventListener('input', updateMemoCount);
  issueContent.addEventListener('input', updateIssueCount);

  // バリデーション関数
  function validateForm() {
    // 完了状況の必須チェック
    if (!completionStatus.value) {
      showError('完了状況を選択してください。');
      return false;
    }

    // 作業メモの文字数チェック
    if (workMemo.value.length > 1000) {
      showError('作業メモは1000文字以内で入力してください。');
      return false;
    }

    // 異常報告がチェックされている場合の異常内容必須チェック
    if (hasIssue.checked && !issueContent.value.trim()) {
      showError('異常報告にチェックが入っている場合、異常内容の入力は必須です。');
      return false;
    }

    // 異常内容の文字数チェック
    if (issueContent.value.length > 500) {
      showError('異常内容は500文字以内で入力してください。');
      return false;
    }

    return true;
  }

  // 記録確定ボタンのイベントリスナー
  btnConfirm.addEventListener('click', async function() {
    if (!validateForm()) {
      return;
    }

    try {
      // 作業記録の更新データを準備
      const updateData = {
        作業終了時刻: new Date(),
        進捗状況: completionStatus.value,
        備考: workMemo.value || null,
        承認状態: '未承認'
      };

      // 作業記録を更新（テーブルインデックス1: 作業記録）
      const updated = await window.aivicApi.update(1, currentWorkRecord.id, updateData);

      if (updated) {
        // 異常報告がある場合は異常値検出ログに記録（テーブルインデックス4: 異常値検出ログ）
        if (hasIssue.checked && issueContent.value.trim()) {
          const issueData = {
            検出対象テーブル: '作業記録',
            検出対象レコードID: currentWorkRecord.id,
            ユーザーID: 'current-user-id', // 実際の実装では現在のユーザーIDを使用
            異常値種別: '作業員報告',
            検出項目: '作業内容',
            検出値: issueContent.value,
            閾値: '手動報告',
            重要度: '中',
            確認状況: '未確認',
            通知送信フラグ: false,
            検出日時: new Date(),
            作成日時: new Date(),
            更新日時: new Date()
          };

          await window.aivicApi.save(4, issueData);
        }

        // 成功メッセージを表示
        alert('工数記録が正常に確定されました。');

        // 前画面に戻る（実際の実装では適切な画面に遷移）
        history.back();
      } else {
        showError('記録の保存に失敗しました。もう一度お試しください。');
      }
    } catch (error) {
      console.error('記録確定エラー:', error);
      showError('記録の保存中にエラーが発生しました。');
    }
  });

  // キャンセルボタンのイベントリスナー
  btnCancel.addEventListener('click', function() {
    if (workMemo.value || issueContent.value || completionStatus.value) {
      if (!confirm('入力内容が失われますが、よろしいですか？')) {
        return;
      }
    }
    history.back();
  });

  // 記録確認ボタンのイベントリスナー
  btnRecordCheck.addEventListener('click', function() {
    window.showScreen("scr-1778907226171");
  });

  // ホバー効果
  btnCancel.addEventListener('mouseenter', function() {
    this.style.background = 'rgba(255,255,255,0.05)';
  });
  btnCancel.addEventListener('mouseleave', function() {
    this.style.background = 'transparent';
  });

  btnConfirm.addEventListener('mouseenter', function() {
    this.style.background = 'var(--primary-hover)';
  });
  btnConfirm.addEventListener('mouseleave', function() {
    this.style.background = 'var(--primary)';
  });

  btnRecordCheck.addEventListener('mouseenter', function() {
    this.style.background = 'rgba(255,255,255,0.05)';
  });
  btnRecordCheck.addEventListener('mouseleave', function() {
    this.style.background = 'transparent';
  });

  // 初期化時に時刻情報を更新（実際の実装では前画面からのデータを使用）
  container.querySelector('#work-item-name').textContent = currentWorkRecord.workItemName;
  container.querySelector('#start-time').textContent = currentWorkRecord.startTime;
  container.querySelector('#end-time').textContent = currentWorkRecord.endTime;
  container.querySelector('#total-time').textContent = currentWorkRecord.totalTime;
  container.querySelector('#break-time').textContent = currentWorkRecord.breakTime;
  container.querySelector('#actual-work-time').textContent = currentWorkRecord.actualWorkTime;
}

function(container, apiUrl, tables) {
  let autoSaveInterval = null;
  let currentSaveIntervalSeconds = 30;
  let isOnline = navigator.onLine;
  let pendingSyncCount = 0;

  // ローカルストレージキー
  const LOCAL_STORAGE_KEY = 'workRecordLocalData';
  const SETTINGS_KEY = 'autoSaveSettings';

  // 要素の取得
  const autoSaveStatus = container.querySelector('#auto-save-status');
  const networkStatus = container.querySelector('#network-status');
  const pendingSyncCountEl = container.querySelector('#pending-sync-count');
  const lastSaveTime = container.querySelector('#last-save-time');
  const saveIntervalInput = container.querySelector('#save-interval');
  const errorNotification = container.querySelector('#error-notification');
  const errorMessage = container.querySelector('#error-message');
  const recoveryNotification = container.querySelector('#recovery-notification');
  const localDataTbody = container.querySelector('#local-data-tbody');
  const noLocalDataEl = container.querySelector('#no-local-data');

  // ローカルデータ再描画関数
  function renderLocalData() {
    const localData = getLocalData();

    if (localData.length === 0) {
      localDataTbody.innerHTML = '';
      noLocalDataEl.style.display = 'block';
      return;
    }

    noLocalDataEl.style.display = 'none';
    localDataTbody.innerHTML = localData.map(item => `
      <tr data-id="${item.id}">
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatDateTime(item.作業日)}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${item.作業内容 || '未入力'}</td>
        <td style="padding: 6px 10px; font-size: 13px;">
          <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; ${item.synced ? 'background: rgba(34, 197, 94, 0.2); color: #22c55e;' : 'background: rgba(251, 191, 36, 0.2); color: #f59e0b;'}">
            ${item.synced ? '同期済み' : '未同期'}
          </span>
        </td>
        <td style="padding: 6px 10px;">
          ${!item.synced ? `<button class="action-btn secondary sync-item-btn" data-id="${item.id}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 2px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">同期</button>` : ''}
          <button class="action-btn secondary delete-local-btn" data-id="${item.id}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 2px 8px; border-radius: 4px; font-size: 11px; cursor: pointer; margin-left: 4px;">削除</button>
        </td>
      </tr>
    `).join('');

    updatePendingSyncCount();
  }

  // ローカルデータ取得
  function getLocalData() {
    try {
      return JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '[]');
    } catch (e) {
      return [];
    }
  }

  // ローカルデータ保存
  function saveLocalData(data) {
    try {
      localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(data));
      return true;
    } catch (e) {
      showError('ストレージ容量不足のため保存に失敗しました。不要なデータを削除してください。');
      return false;
    }
  }

  // 設定の読み込み
  function loadSettings() {
    try {
      const settings = JSON.parse(localStorage.getItem(SETTINGS_KEY) || '{}');
      currentSaveIntervalSeconds = settings.saveInterval || 30;
      saveIntervalInput.value = currentSaveIntervalSeconds;
    } catch (e) {
      currentSaveIntervalSeconds = 30;
    }
  }

  // 設定の保存
  function saveSettings() {
    const settings = {
      saveInterval: currentSaveIntervalSeconds
    };
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
  }

  // エラー表示
  function showError(message) {
    errorMessage.textContent = message;
    errorNotification.style.display = 'block';
    setTimeout(() => {
      errorNotification.style.display = 'none';
    }, 5000);
  }

  // 日時フォーマット
  function formatDateTime(dateStr) {
    if (!dateStr) return '--:--';
    const date = new Date(dateStr);
    return `${date.getMonth() + 1}/${date.getDate()} ${date.getHours().toString().padStart(2, '0')}:${date.getMinutes().toString().padStart(2, '0')}`;
  }

  // 同期待ち件数更新
  function updatePendingSyncCount() {
    const localData = getLocalData();
    pendingSyncCount = localData.filter(item => !item.synced).length;
    pendingSyncCountEl.textContent = `${pendingSyncCount}件`;

    // 上限チェック（100件）
    if (pendingSyncCount >= 100) {
      showError('同期待ちデータが上限（100件）に達しました。手動同期を実行してください。');
    }
  }

  // ネットワーク状態更新
  function updateNetworkStatus() {
    isOnline = navigator.onLine;
    networkStatus.textContent = isOnline ? 'オンライン' : 'オフライン';
    networkStatus.style.color = isOnline ? '#22c55e' : '#f59e0b';

    if (isOnline) {
      autoSyncPendingData();
    }
  }

  // 自動保存開始
  function startAutoSave() {
    if (autoSaveInterval) {
      clearInterval(autoSaveInterval);
    }

    autoSaveInterval = setInterval(() => {
      performAutoSave();
    }, currentSaveIntervalSeconds * 1000);

    autoSaveStatus.textContent = '有効';
    autoSaveStatus.style.color = '#22c55e';
  }

  // 自動保存停止
  function stopAutoSave() {
    if (autoSaveInterval) {
      clearInterval(autoSaveInterval);
      autoSaveInterval = null;
    }
    autoSaveStatus.textContent = '無効';
    autoSaveStatus.style.color = '#f59e0b';
  }

  // 自動保存実行
  async function performAutoSave() {
    // 現在の画面から作業データを取得（実際の実装では工数記録画面のデータを取得）
    const workData = {
      id: Date.now().toString(),
      作業員ID: 'current-user-id',
      作業日: new Date().toISOString(),
      作業開始時刻: new Date().toISOString(),
      作業内容: 'サンプル作業内容',
      プロジェクト名: 'サンプルプロジェクト',
      作業場所: 'サンプル現場',
      作業種別: '点検',
      進捗状況: '作業中',
      承認状態: '未承認',
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      作成者ID: 'current-user-id',
      synced: false
    };

    if (isOnline) {
      try {
        // オンライン時はサーバーに保存
        const saved = await window.aivicApi.save(1, workData);
        if (saved) {
          workData.synced = true;
          lastSaveTime.textContent = formatDateTime(new Date().toISOString());
        } else {
          // サーバー保存失敗時はローカルに保存
          saveToLocal(workData);
          showError('サーバーへの保存に失敗しました。ローカルに保存されました。');
        }
      } catch (error) {
        saveToLocal(workData);
        showError('サーバーエラーが発生しました。ローカルに保存されました。');
      }
    } else {
      // オフライン時はローカルに保存
      saveToLocal(workData);
    }

    renderLocalData();
  }

  // ローカル保存
  function saveToLocal(data) {
    const localData = getLocalData();

    if (localData.length >= 100) {
      showError('ローカルデータが上限に達しています。同期を実行してください。');
      return false;
    }

    localData.push(data);
    return saveLocalData(localData);
  }

  // 未同期データの自動同期
  async function autoSyncPendingData() {
    if (!isOnline) return;

    const localData = getLocalData();
    const pendingData = localData.filter(item => !item.synced);

    for (const item of pendingData) {
      try {
        const saved = await window.aivicApi.save(1, item);
        if (saved) {
          item.synced = true;
          lastSaveTime.textContent = formatDateTime(new Date().toISOString());
        }
      } catch (error) {
        console.error('Auto sync failed for item:', item.id);
        break; // 1件でも失敗したら停止
      }
    }

    saveLocalData(localData);
    renderLocalData();
  }

  // 手動同期
  async function performManualSync() {
    if (!isOnline) {
      showError('ネットワークに接続されていません。');
      return;
    }

    const localData = getLocalData();
    const pendingData = localData.filter(item => !item.synced);

    if (pendingData.length === 0) {
      showError('同期するデータがありません。');
      return;
    }

    let syncedCount = 0;
    let retryCount = 0;
    const maxRetries = 3;

    for (const item of pendingData) {
      let success = false;

      for (let i = 0; i < maxRetries && !success; i++) {
        try {
          const saved = await window.aivicApi.save(1, item);
          if (saved) {
            item.synced = true;
            syncedCount++;
            success = true;
          } else {
            retryCount++;
          }
        } catch (error) {
          retryCount++;
          if (i === maxRetries - 1) {
            showError(`データの同期に失敗しました。リトライ回数: ${retryCount}`);
          }
        }
      }
    }

    saveLocalData(localData);
    renderLocalData();
    lastSaveTime.textContent = formatDateTime(new Date().toISOString());

    if (syncedCount > 0) {
      showError(`${syncedCount}件のデータを同期しました。`);
      errorNotification.style.background = 'rgba(34, 197, 94, 0.1)';
      errorNotification.style.borderColor = 'rgba(34, 197, 94, 0.3)';
    }
  }

  // データ復旧チェック
  function checkForRecoveryData() {
    const localData = getLocalData();
    const unsyncedData = localData.filter(item => !item.synced);

    if (unsyncedData.length > 0) {
      recoveryNotification.style.display = 'block';
    }
  }

  // 初期化
  loadSettings();
  renderLocalData();
  updateNetworkStatus();
  startAutoSave();
  checkForRecoveryData();

  // ネットワーク状態監視
  window.addEventListener('online', updateNetworkStatus);
  window.addEventListener('offline', updateNetworkStatus);

  // 設定保存ボタン
  container.querySelector('#btn-save-settings').addEventListener('click', () => {
    const newInterval = parseInt(saveIntervalInput.value);

    if (newInterval < 1) {
      showError('保存間隔は1秒以上で設定してください。');
      return;
    }

    if (newInterval > 86400) {
      showError('保存間隔は86400秒以下で設定してください。');
      return;
    }

    currentSaveIntervalSeconds = newInterval;
    saveSettings();
    startAutoSave(); // 新しい間隔で再開

    showError('保存間隔を更新しました。');
    errorNotification.style.background = 'rgba(34, 197, 94, 0.1)';
    errorNotification.style.borderColor = 'rgba(34, 197, 94, 0.3)';
  });

  // 手動同期ボタン
  container.querySelector('#btn-manual-sync').addEventListener('click', performManualSync);

  // データ復旧ボタン
  container.querySelector('#btn-recover-data').addEventListener('click', () => {
    recoveryNotification.style.display = 'none';
    showError('データを復旧しました。');
    errorNotification.style.background = 'rgba(34, 197, 94, 0.1)';
    errorNotification.style.borderColor = 'rgba(34, 197, 94, 0.3)';
  });

  // データ破棄ボタン
  container.querySelector('#btn-discard-data').addEventListener('click', () => {
    const localData = getLocalData();
    const syncedData = localData.filter(item => item.synced);
    saveLocalData(syncedData);
    renderLocalData();
    recoveryNotification.style.display = 'none';
  });

  // ローカルデータクリアボタン
  container.querySelector('#btn-clear-local').addEventListener('click', () => {
    if (!confirm('すべてのローカルデータを削除しますか？未同期のデータは失われます。')) return;

    localStorage.removeItem(LOCAL_STORAGE_KEY);
    renderLocalData();
  });

  // ローカルデータ操作（イベントデリゲーション）
  container.addEventListener('click', async (e) => {
    // 個別同期
    const syncBtn = e.target.closest('.sync-item-btn');
    if (syncBtn) {
      if (!isOnline) {
        showError('ネットワークに接続されていません。');
        return;
      }

      const itemId = syncBtn.dataset.id;
      const localData = getLocalData();
      const item = localData.find(d => d.id === itemId);

      if (item) {
        try {
          const saved = await window.aivicApi.save(1, item);
          if (saved) {
            item.synced = true;
            saveLocalData(localData);
            renderLocalData();
            lastSaveTime.textContent = formatDateTime(new Date().toISOString());
          } else {
            showError('同期に失敗しました。');
          }
        } catch (error) {
          showError('同期エラーが発生しました。');
        }
      }
    }

    // ローカルデータ削除
    const deleteBtn = e.target.closest('.delete-local-btn');
    if (deleteBtn) {
      if (!confirm('このローカルデータを削除しますか？')) return;

      const itemId = deleteBtn.dataset.id;
      const localData = getLocalData();
      const filteredData = localData.filter(d => d.id !== itemId);
      saveLocalData(filteredData);
      renderLocalData();
    }
  });

  // ナビゲーションボタン
  container.querySelector('#btn-work-record').addEventListener('click', () => {
    window.showScreen('scr-1778907133295');
  });

  container.querySelector('#btn-work-history').addEventListener('click', () => {
    window.showScreen('scr-1778907145716');
  });
}

function(container, apiUrl, tables) {
  let currentRecords = [];
  let deleteTargetId = null;

  // 時刻フォーマット関数
  function formatTime(timestamp) {
    if (!timestamp) return '-';
    const date = new Date(timestamp);
    return date.toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
  }

  // 日付フォーマット関数
  function formatDate(timestamp) {
    if (!timestamp) return '-';
    const date = new Date(timestamp);
    return date.toLocaleDateString('ja-JP');
  }

  // 作業時間フォーマット関数
  function formatWorkTime(minutes) {
    if (!minutes || minutes <= 0) return '-';
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return `${hours}時間${mins}分`;
  }

  // 異常値チェック関数
  function checkAbnormalValues(record) {
    const warnings = [];

    // 24時間を超える作業時間
    if (record.作業時間 && record.作業時間 > 1440) {
      warnings.push('24時間超過');
    }

    // 終了時刻が開始時刻より早い
    if (record.作業開始時刻 && record.作業終了時刻) {
      const start = new Date(record.作業開始時刻);
      const end = new Date(record.作業終了時刻);
      if (end < start) {
        warnings.push('時刻異常');
      }
    }

    // 中断時間が作業時間を超える
    if (record.作業時間 && record.中断記録) {
      const totalBreakTime = record.中断記録.reduce((sum, br) => sum + (br.中断時間 || 0), 0);
      if (totalBreakTime > record.作業時間) {
        warnings.push('中断時間異常');
      }
    }

    return warnings;
  }

  // 権限チェック関数
  function canEdit(record) {
    return record.承認状態 !== '承認済み';
  }

  function canDelete(record) {
    return record.承認状態 !== '承認済み';
  }

  // テーブル再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector('#records-tbody');
    const emptyState = container.querySelector('#empty-state');

    if (!rows || rows.length === 0) {
      tbody.innerHTML = '';
      emptyState.classList.remove('hidden');
      return;
    }

    emptyState.classList.add('hidden');

    tbody.innerHTML = rows.map(record => {
      const warnings = checkAbnormalValues(record);
      const warningIcon = warnings.length > 0 ? 
        `<span style="color: #dc3545; margin-left: 4px;" title="${warnings.join(', ')}">⚠️</span>` : '';

      // 中断時間の計算
      let totalBreakTime = 0;
      if (record.中断記録 && Array.isArray(record.中断記録)) {
        totalBreakTime = record.中断記録.reduce((sum, br) => sum + (br.中断時間 || 0), 0);
      }

      const editDisabled = !canEdit(record);
      const deleteDisabled = !canDelete(record);

      return `
        <tr data-id="${record.作業記録ID}" style="height: 36px;">
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.02);">
            ${formatDate(record.作業日)}${warningIcon}
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.02);">
            ${formatTime(record.作業開始時刻)}
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.02);">
            ${formatTime(record.作業終了時刻)}
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.02);">
            ${formatWorkTime(record.作業時間)}
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.02);">
            ${formatWorkTime(totalBreakTime)}
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.02);">
            ${record.プロジェクト名 || '-'}
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.02);">
            ${record.作業場所 || '-'}
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.02);">
            ${record.作業種別 || '-'}
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.02);">
            <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; background: ${record.承認状態 === '承認済み' ? '#28a745' : record.承認状態 === '差し戻し' ? '#dc3545' : '#6c757d'}; color: #fff;">
              ${record.承認状態 || '未承認'}
            </span>
          </td>
          <td style="padding: 6px 10px; font-size: 13px; border-bottom: 1px solid rgba(255,255,255,0.02);">
            <div style="display: flex; gap: 4px;">
              <button class="detail-btn" data-id="${record.作業記録ID}" style="background: var(--primary); color: #fff; border: none; padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">詳細</button>
              <button class="edit-btn" data-id="${record.作業記録ID}" ${editDisabled ? 'disabled' : ''} style="background: ${editDisabled ? '#6c757d' : 'transparent'}; color: ${editDisabled ? '#fff' : 'var(--text)'}; border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: ${editDisabled ? 'not-allowed' : 'pointer'};">修正</button>
              <button class="delete-btn" data-id="${record.作業記録ID}" ${deleteDisabled ? 'disabled' : ''} style="background: ${deleteDisabled ? '#6c757d' : '#dc3545'}; color: #fff; border: none; padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: ${deleteDisabled ? 'not-allowed' : 'pointer'};">削除</button>
            </div>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 詳細表示関数
  function showDetail(record) {
    const modal = container.querySelector('#detail-modal');
    const content = container.querySelector('#detail-content');

    let breakTimeHtml = '';
    if (record.中断記録 && Array.isArray(record.中断記録) && record.中断記録.length > 0) {
      breakTimeHtml = `
        <div style="margin-top: 12px;">
          <strong>中断記録:</strong>
          ${record.中断記録.map(br => `
            <div style="margin-left: 16px; margin-top: 4px; font-size: 12px;">
              • ${formatTime(br.中断開始日時)} - ${formatTime(br.中断終了日時)} (${formatWorkTime(br.中断時間)})<br>
              　理由: ${br.中断理由区分 || '-'} ${br.中断理由詳細 ? `- ${br.中断理由詳細}` : ''}
            </div>
          `).join('')}
        </div>
      `;
    }

    content.innerHTML = `
      <div style="display: grid; grid-template-columns: 120px 1fr; gap: 8px; line-height: 1.8;">
        <div><strong>作業日:</strong></div>
        <div>${formatDate(record.作業日)}</div>

        <div><strong>開始時刻:</strong></div>
        <div>${formatTime(record.作業開始時刻)}</div>

        <div><strong>終了時刻:</strong></div>
        <div>${formatTime(record.作業終了時刻)}</div>

        <div><strong>作業時間:</strong></div>
        <div>${formatWorkTime(record.作業時間)}</div>

        <div><strong>プロジェクト:</strong></div>
        <div>${record.プロジェクト名 || '-'}</div>

        <div><strong>作業場所:</strong></div>
        <div>${record.作業場所 || '-'}</div>

        <div><strong>作業種別:</strong></div>
        <div>${record.作業種別 || '-'}</div>

        <div><strong>作業内容:</strong></div>
        <div>${record.作業内容 || '-'}</div>

        <div><strong>進捗状況:</strong></div>
        <div>${record.進捗状況 || '-'}</div>

        <div><strong>承認状態:</strong></div>
        <div>${record.承認状態 || '未承認'}</div>

        <div><strong>備考:</strong></div>
        <div>${record.備考 || '-'}</div>
      </div>
      ${breakTimeHtml}
    `;

    modal.classList.remove('hidden');
  }

  // CSVエクスポート関数
  function exportCSV() {
    const headers = ['日付', '開始時刻', '終了時刻', '作業時間', '中断時間', 'プロジェクト', '作業場所', '作業種別', '作業内容', '承認状態', '備考'];

    const csvContent = [
      headers.join(','),
      ...currentRecords.map(record => {
        let totalBreakTime = 0;
        if (record.中断記録 && Array.isArray(record.中断記録)) {
          totalBreakTime = record.中断記録.reduce((sum, br) => sum + (br.中断時間 || 0), 0);
        }

        return [
          formatDate(record.作業日),
          formatTime(record.作業開始時刻),
          formatTime(record.作業終了時刻),
          formatWorkTime(record.作業時間),
          formatWorkTime(totalBreakTime),
          `"${(record.プロジェクト名 || '').replace(/"/g, '""')}"`,
          `"${(record.作業場所 || '').replace(/"/g, '""')}"`,
          `"${(record.作業種別 || '').replace(/"/g, '""')}"`,
          `"${(record.作業内容 || '').replace(/"/g, '""')}"`,
          record.承認状態 || '未承認',
          `"${(record.備考 || '').replace(/"/g, '""')}"`
        ].join(',');
      })
    ].join('\n');

    const blob = new Blob(['\uFEFF' + csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `作業記録_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // フィルタリング関数
  function filterRecords() {
    const datePicker = container.querySelector('#date-picker').value;
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;

    // 日付範囲の妥当性チェック
    if (startDate && endDate && startDate > endDate) {
      alert('開始日は終了日より前の日付を指定してください');
      return;
    }

    window.aivicApi.list(1).then(rows => {
      if (!rows) return;

      let filtered = rows;

      // 単一日付フィルタ
      if (datePicker) {
        filtered = filtered.filter(record => {
          const recordDate = new Date(record.作業日).toISOString().split('T')[0];
          return recordDate === datePicker;
        });
      }

      // 期間フィルタ
      if (startDate || endDate) {
        filtered = filtered.filter(record => {
          const recordDate = new Date(record.作業日).toISOString().split('T')[0];
          if (startDate && recordDate < startDate) return false;
          if (endDate && recordDate > endDate) return false;
          return true;
        });
      }

      currentRecords = filtered;
      renderRows(filtered);
    });
  }

  // 初期データ読み込み
  window.aivicApi.list(1).then(rows => {
    if (rows) {
      currentRecords = rows;
      renderRows(rows);
    }
  });

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#date-picker').value = today;

  // イベントリスナー設定

  // 絞り込みボタン
  container.querySelector('#btn-filter').addEventListener('click', filterRecords);

  // 日付選択での自動フィルタ
  container.querySelector('#date-picker').addEventListener('change', filterRecords);

  // CSVエクスポートボタン
  container.querySelector('#btn-csv-export').addEventListener('click', exportCSV);

  // メニューに戻るボタン
  container.querySelector('#btn-menu').addEventListener('click', () => {
    window.showScreen("scr-1778907133295");
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    // 詳細表示
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      const record = currentRecords.find(r => r.作業記録ID === id);
      if (record) {
        showDetail(record);
      }
      return;
    }

    // 編集
    const editBtn = e.target.closest('.edit-btn');
    if (editBtn && !editBtn.disabled) {
      const id = editBtn.dataset.id;
      const record = currentRecords.find(r => r.作業記録ID === id);
      if (record && canEdit(record)) {
        window.showScreen("scr-1778907343735");
      } else {
        alert('承認済みの記録は修正できません');
      }
      return;
    }

    // 削除
    const deleteBtn = e.target.closest('.delete-btn');
    if (deleteBtn && !deleteBtn.disabled) {
      const id = deleteBtn.dataset.id;
      const record = currentRecords.find(r => r.作業記録ID === id);
      if (record && canDelete(record)) {
        deleteTargetId = id;
        container.querySelector('#delete-modal').classList.remove('hidden');
      } else {
        alert('承認済みの記録は削除できません');
      }
      return;
    }
  });

  // 詳細モーダルを閉じる
  container.querySelector('#close-detail').addEventListener('click', () => {
    container.querySelector('#detail-modal').classList.add('hidden');
  });

  // 削除確認モーダル
  container.querySelector('#cancel-delete').addEventListener('click', () => {
    container.querySelector('#delete-modal').classList.add('hidden');
    deleteTargetId = null;
  });

  container.querySelector('#confirm-delete').addEventListener('click', async () => {
    if (deleteTargetId) {
      await window.aivicApi.delete(1, deleteTargetId);
      container.querySelector('#delete-modal').classList.add('hidden');
      deleteTargetId = null;

      // データを再読み込み
      window.aivicApi.list(1).then(rows => {
        if (rows) {
          currentRecords = rows;
          filterRecords(); // 現在のフィルタを適用
        }
      });
    }
  });

  // モーダル背景クリックで閉じる
  container.querySelector('#detail-modal').addEventListener('click', (e) => {
    if (e.target === container.querySelector('#detail-modal')) {
      container.querySelector('#detail-modal').classList.add('hidden');
    }
  });

  container.querySelector('#delete-modal').addEventListener('click', (e) => {
    if (e.target === container.querySelector('#delete-modal')) {
      container.querySelector('#delete-modal').classList.add('hidden');
      deleteTargetId = null;
    }
  });
}

function(container, apiUrl, tables) {
  let mediaRecorder = null;
  let recordingChunks = [];
  let recordingTimer = null;
  let recordingStartTime = null;

  // 現在時刻を設定
  const now = new Date();
  const startTimeInput = container.querySelector('#start-time');
  startTimeInput.value = now.toISOString().slice(0, 16);

  // 関連作業項目を表示（最新の作業記録から取得）
  function loadCurrentWorkItem() {
    if (tables[1] && tables[1].records) {
      const workRecords = tables[1].records.filter(r => r.進捗状況 === '作業中');
      if (workRecords.length > 0) {
        const currentWork = workRecords[workRecords.length - 1];
        container.querySelector('#work-item').textContent = `${currentWork.プロジェクト名} - ${currentWork.作業種別}`;
      }
    }
  }

  // 中断時間を計算
  function calculateDuration() {
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;

    if (startTime && endTime) {
      const start = new Date(startTime);
      const end = new Date(endTime);
      const diffMs = end - start;

      if (diffMs > 0) {
        const hours = Math.floor(diffMs / (1000 * 60 * 60));
        const minutes = Math.floor((diffMs % (1000 * 60 * 60)) / (1000 * 60));
        container.querySelector('#duration').textContent = `${hours}時間${minutes}分`;
      } else {
        container.querySelector('#duration').textContent = '-';
      }
    } else {
      container.querySelector('#duration').textContent = '-';
    }
  }

  // 文字数カウント
  function updateCharCount() {
    const details = container.querySelector('#details');
    const charCount = container.querySelector('#char-count');
    charCount.textContent = details.value.length;
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
    setTimeout(() => {
      errorDiv.style.display = 'none';
    }, 5000);
  }

  // バリデーション
  function validateForm() {
    const startTime = container.querySelector('#start-time').value;
    const reason = container.querySelector('#reason').value;
    const endTime = container.querySelector('#end-time').value;

    if (!startTime) {
      showError('中断開始時刻は必須です');
      return false;
    }

    if (!reason) {
      showError('中断理由は必須です');
      return false;
    }

    // 未来時刻チェック
    const now = new Date();
    const startDate = new Date(startTime);
    if (startDate > now) {
      showError('未来の時刻は入力できません');
      return false;
    }

    if (endTime) {
      const endDate = new Date(endTime);
      if (endDate > now) {
        showError('未来の時刻は入力できません');
        return false;
      }
      if (endDate <= startDate) {
        showError('終了時刻は開始時刻より後である必要があります');
        return false;
      }
    }

    // 文字数チェック
    const details = container.querySelector('#details').value;
    if (details.length > 1000) {
      showError('中断詳細は1000文字以内で入力してください');
      return false;
    }

    return true;
  }

  // 影響範囲の全選択/全解除
  function setupImpactSelection() {
    const selectAllCheckbox = container.querySelector('#select-all');
    const impactCheckboxes = container.querySelectorAll('input[name="impact"]');

    selectAllCheckbox.addEventListener('change', () => {
      impactCheckboxes.forEach(cb => {
        cb.checked = selectAllCheckbox.checked;
      });
    });

    impactCheckboxes.forEach(cb => {
      cb.addEventListener('change', () => {
        const allChecked = Array.from(impactCheckboxes).every(checkbox => checkbox.checked);
        const noneChecked = Array.from(impactCheckboxes).every(checkbox => !checkbox.checked);

        if (allChecked) {
          selectAllCheckbox.checked = true;
          selectAllCheckbox.indeterminate = false;
        } else if (noneChecked) {
          selectAllCheckbox.checked = false;
          selectAllCheckbox.indeterminate = false;
        } else {
          selectAllCheckbox.checked = false;
          selectAllCheckbox.indeterminate = true;
        }
      });
    });
  }

  // 写真アップロード
  function setupPhotoUpload() {
    const photoBtn = container.querySelector('#photo-btn');
    const photoInput = container.querySelector('#photo-upload');
    const photoPreview = container.querySelector('#photo-preview');
    const previewImg = container.querySelector('#preview-img');
    const photoName = container.querySelector('#photo-name');

    photoBtn.addEventListener('click', () => {
      photoInput.click();
    });

    photoInput.addEventListener('change', (e) => {
      const file = e.target.files[0];
      if (!file) return;

      // ファイル形式チェック
      if (!file.type.startsWith('image/')) {
        showError('画像ファイルのみアップロード可能です');
        return;
      }

      // ファイルサイズチェック（10MB）
      if (file.size > 10 * 1024 * 1024) {
        showError('ファイルサイズは10MB以下にしてください');
        return;
      }

      const reader = new FileReader();
      reader.onload = (e) => {
        previewImg.src = e.target.result;
        photoName.textContent = file.name;
        photoPreview.style.display = 'block';
        photoBtn.textContent = '📷 写真を変更';
      };
      reader.readAsDataURL(file);
    });
  }

  // 音声録音
  function setupAudioRecording() {
    const recordBtn = container.querySelector('#record-btn');
    const recordingStatus = container.querySelector('#recording-status');
    const recordTime = container.querySelector('#record-time');
    const audioPreview = container.querySelector('#audio-preview');

    recordBtn.addEventListener('click', async () => {
      if (!mediaRecorder || mediaRecorder.state === 'inactive') {
        try {
          const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
          mediaRecorder = new MediaRecorder(stream);
          recordingChunks = [];

          mediaRecorder.ondataavailable = (e) => {
            if (e.data.size > 0) {
              recordingChunks.push(e.data);
            }
          };

          mediaRecorder.onstop = () => {
            const blob = new Blob(recordingChunks, { type: 'audio/webm' });
            const audioUrl = URL.createObjectURL(blob);
            const audio = audioPreview.querySelector('audio');
            audio.src = audioUrl;
            audioPreview.style.display = 'block';

            stream.getTracks().forEach(track => track.stop());
          };

          mediaRecorder.start();
          recordBtn.textContent = '⏹️ 録音停止';
          recordingStatus.style.display = 'block';
          recordingStartTime = Date.now();

          recordingTimer = setInterval(() => {
            const elapsed = Math.floor((Date.now() - recordingStartTime) / 1000);
            const minutes = Math.floor(elapsed / 60);
            const seconds = elapsed % 60;
            recordTime.textContent = `${minutes}:${seconds.toString().padStart(2, '0')}`;
          }, 1000);

        } catch (error) {
          showError('マイクへのアクセスが拒否されました。録音機能を使用するにはマイクの許可が必要です。');
        }
      } else {
        mediaRecorder.stop();
        recordBtn.textContent = '🎤 録音開始';
        recordingStatus.style.display = 'none';
        if (recordingTimer) {
          clearInterval(recordingTimer);
          recordingTimer = null;
        }
      }
    });
  }

  // 一時保存
  async function tempSave() {
    const formData = collectFormData();
    localStorage.setItem('interruption_temp_save', JSON.stringify(formData));

    // 成功メッセージを表示
    const tempBtn = container.querySelector('#temp-save-btn');
    const originalText = tempBtn.textContent;
    tempBtn.textContent = '保存完了';
    tempBtn.style.background = 'var(--primary)';
    tempBtn.style.color = '#fff';

    setTimeout(() => {
      tempBtn.textContent = originalText;
      tempBtn.style.background = 'transparent';
      tempBtn.style.color = 'var(--text)';
    }, 2000);
  }

  // 一時保存データの復元
  function restoreTempSave() {
    const tempData = localStorage.getItem('interruption_temp_save');
    if (tempData) {
      try {
        const data = JSON.parse(tempData);
        if (data.中断開始日時) container.querySelector('#start-time').value = data.中断開始日時.slice(0, 16);
        if (data.中断終了日時) container.querySelector('#end-time').value = data.中断終了日時.slice(0, 16);
        if (data.中断理由区分) container.querySelector('#reason').value = data.中断理由区分;
        if (data.中断場所) container.querySelector('#location').value = data.中断場所;
        if (data.中断理由詳細) container.querySelector('#details').value = data.中断理由詳細;
        if (data.緊急度) {
          const urgencyRadio = container.querySelector(`input[name="urgency"][value="${data.緊急度}"]`);
          if (urgencyRadio) urgencyRadio.checked = true;
        }
        if (data.影響範囲 && Array.isArray(data.影響範囲)) {
          data.影響範囲.forEach(impact => {
            const checkbox = container.querySelector(`input[name="impact"][value="${impact}"]`);
            if (checkbox) checkbox.checked = true;
          });
        }
        updateCharCount();
        calculateDuration();
      } catch (error) {
        console.error('一時保存データの復元に失敗しました:', error);
      }
    }
  }

  // フォームデータ収集
  function collectFormData() {
    const urgencyRadio = container.querySelector('input[name="urgency"]:checked');
    const impactCheckboxes = container.querySelectorAll('input[name="impact"]:checked');

    return {
      中断開始日時: container.querySelector('#start-time').value,
      中断終了日時: container.querySelector('#end-time').value || null,
      中断理由区分: container.querySelector('#reason').value,
      中断理由詳細: container.querySelector('#details').value,
      中断場所: container.querySelector('#location').value,
      緊急度: urgencyRadio ? urgencyRadio.value : '中',
      影響範囲: Array.from(impactCheckboxes).map(cb => cb.value),
      作業記録ID: null, // 実際の実装では現在の作業記録IDを設定
      対応状況: '未対応',
      記録者ID: null // 実際の実装では現在のユーザーIDを設定
    };
  }

  // 記録完了
  async function completeRecord() {
    if (!validateForm()) return;

    try {
      const formData = collectFormData();

      // 中断時間を計算
      if (formData.中断開始日時 && formData.中断終了日時) {
        const start = new Date(formData.中断開始日時);
        const end = new Date(formData.中断終了日時);
        formData.中断時間 = Math.floor((end - start) / (1000 * 60)); // 分単位
      }

      const saved = await window.aivicApi.save(2, formData); // 中断記録テーブルのインデックス

      if (saved) {
        // 一時保存データを削除
        localStorage.removeItem('interruption_temp_save');

        // 作業再開記録画面に遷移
        window.showScreen("scr-1778907251446");
      } else {
        showError('記録の保存に失敗しました。ネットワーク接続を確認してください。');
      }
    } catch (error) {
      console.error('記録保存エラー:', error);
      showError('記録の保存中にエラーが発生しました。');
    }
  }

  // イベントリスナー設定
  container.querySelector('#start-time').addEventListener('change', calculateDuration);
  container.querySelector('#end-time').addEventListener('change', calculateDuration);
  container.querySelector('#details').addEventListener('input', updateCharCount);
  container.querySelector('#temp-save-btn').addEventListener('click', tempSave);
  container.querySelector('#complete-btn').addEventListener('click', completeRecord);

  // ボタンホバー効果
  container.querySelector('#photo-btn').addEventListener('mouseenter', (e) => {
    e.target.style.background = 'rgba(255,255,255,0.05)';
  });
  container.querySelector('#photo-btn').addEventListener('mouseleave', (e) => {
    e.target.style.background = 'transparent';
  });

  container.querySelector('#record-btn').addEventListener('mouseenter', (e) => {
    e.target.style.background = 'rgba(255,255,255,0.05)';
  });
  container.querySelector('#record-btn').addEventListener('mouseleave', (e) => {
    e.target.style.background = 'transparent';
  });

  container.querySelector('#temp-save-btn').addEventListener('mouseenter', (e) => {
    e.target.style.background = 'rgba(255,255,255,0.05)';
  });
  container.querySelector('#temp-save-btn').addEventListener('mouseleave', (e) => {
    e.target.style.background = 'transparent';
  });

  container.querySelector('#complete-btn').addEventListener('mouseenter', (e) => {
    e.target.style.background = 'var(--primary-hover)';
  });
  container.querySelector('#complete-btn').addEventListener('mouseleave', (e) => {
    e.target.style.background = 'var(--primary)';
  });

  // 初期化
  loadCurrentWorkItem();
  calculateDuration();
  updateCharCount();
  setupImpactSelection();
  setupPhotoUpload();
  setupAudioRecording();
  restoreTempSave();
}

function(container, apiUrl, tables) {
  let selectedWorkRecord = null;
  let selectedSuspendRecord = null;

  // 現在時刻を取得してフォーマット
  function getCurrentDateTime() {
    const now = new Date();
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const day = String(now.getDate()).padStart(2, '0');
    const hours = String(now.getHours()).padStart(2, '0');
    const minutes = String(now.getMinutes()).padStart(2, '0');
    return `${year}-${month}-${day}T${hours}:${minutes}`;
  }

  // 日時フォーマット関数
  function formatDateTime(dateStr) {
    if (!dateStr) return '-';
    const date = new Date(dateStr);
    return date.toLocaleString('ja-JP', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit'
    });
  }

  // 中断中作業一覧の再描画
  function renderSuspendedWorks(workRecords, suspendRecords) {
    const tbody = container.querySelector('#suspended-work-tbody');
    const noWorkDiv = container.querySelector('#no-suspended-work');

    // 中断中の作業記録を抽出（進捗状況が「中断」のもの）
    const suspendedWorks = workRecords.filter(work => work.進捗状況 === '中断');

    if (suspendedWorks.length === 0) {
      tbody.innerHTML = '';
      noWorkDiv.classList.remove('hidden');
      return;
    }

    noWorkDiv.classList.add('hidden');

    tbody.innerHTML = suspendedWorks.map(work => {
      // この作業に関連する最新の中断記録を取得
      const relatedSuspends = suspendRecords.filter(suspend => 
        suspend.作業記録ID === work.作業記録ID && !suspend.中断終了日時
      );
      const latestSuspend = relatedSuspends.length > 0 ? relatedSuspends[relatedSuspends.length - 1] : null;

      return `
        <tr data-work-id="${work.作業記録ID}" data-suspend-id="${latestSuspend?.中断記録ID || ''}" style="cursor: pointer;">
          <td style="padding: 6px 10px; font-size: 13px;">${work.プロジェクト名 || ''} - ${work.作業種別 || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${formatDateTime(latestSuspend?.中断開始日時)}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${latestSuspend?.中断理由区分 || ''}</td>
          <td style="padding: 6px 10px;">
            <button class="action-btn resume-btn" data-work-id="${work.作業記録ID}" data-suspend-id="${latestSuspend?.中断記録ID || ''}" style="padding: 4px 8px; font-size: 12px;">
              再開
            </button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 作業再開フォームを表示
  function showResumeForm(workRecord, suspendRecord) {
    selectedWorkRecord = workRecord;
    selectedSuspendRecord = suspendRecord;

    const resumeForm = container.querySelector('#resume-form');
    const workNameDiv = container.querySelector('#selected-work-name');
    const suspendTimeDiv = container.querySelector('#selected-suspend-time');
    const resumeTimeInput = container.querySelector('#resume-time');

    workNameDiv.textContent = `${workRecord.プロジェクト名 || ''} - ${workRecord.作業種別 || ''}`;
    suspendTimeDiv.textContent = formatDateTime(suspendRecord?.中断開始日時);
    resumeTimeInput.value = getCurrentDateTime();

    resumeForm.classList.remove('hidden');

    // エラーメッセージをクリア
    hideError();
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector('#resume-error');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
  }

  function hideError() {
    const errorDiv = container.querySelector('#resume-error');
    errorDiv.classList.add('hidden');
  }

  // バリデーション
  function validateResumeForm() {
    const resumeTime = container.querySelector('#resume-time').value;
    const reasonSelect = container.querySelector('#resume-reason-select').value;
    const reasonDetail = container.querySelector('#resume-reason-detail').value.trim();

    if (!resumeTime) {
      showError('再開時刻を入力してください');
      return false;
    }

    if (!reasonSelect && !reasonDetail) {
      showError('再開理由を選択するか詳細を入力してください');
      return false;
    }

    if (reasonDetail.length > 500) {
      showError('再開理由は500文字以内で入力してください');
      return false;
    }

    return true;
  }

  // 確認ダイアログを表示
  function showConfirmationDialog() {
    if (!validateResumeForm()) return;

    const dialog = container.querySelector('#resume-confirmation-dialog');
    const workInfo = container.querySelector('#confirmation-work-info');
    const reasonSelect = container.querySelector('#resume-reason-select').value;
    const reasonDetail = container.querySelector('#resume-reason-detail').value.trim();

    const reason = reasonSelect || reasonDetail || '未入力';

    workInfo.innerHTML = `
      作業項目: ${selectedWorkRecord.プロジェクト名} - ${selectedWorkRecord.作業種別}<br>
      再開理由: ${reason}
    `;

    dialog.classList.remove('hidden');
  }

  // 確認ダイアログを非表示
  function hideConfirmationDialog() {
    const dialog = container.querySelector('#resume-confirmation-dialog');
    dialog.classList.add('hidden');
  }

  // 作業再開処理
  async function resumeWork() {
    try {
      const resumeTime = container.querySelector('#resume-time').value;
      const reasonSelect = container.querySelector('#resume-reason-select').value;
      const reasonDetail = container.querySelector('#resume-reason-detail').value.trim();

      const resumeReason = reasonSelect || reasonDetail;

      // 1. 中断記録を終了
      if (selectedSuspendRecord) {
        await window.aivicApi.update(2, selectedSuspendRecord.中断記録ID, {
          中断終了日時: resumeTime,
          対応状況: '解決済み'
        });
      }

      // 2. 作業記録の進捗状況を「作業中」に更新
      await window.aivicApi.update(1, selectedWorkRecord.作業記録ID, {
        進捗状況: '作業中',
        備考: `${selectedWorkRecord.備考 || ''}\n[${formatDateTime(resumeTime)}] 作業再開: ${resumeReason}`.trim()
      });

      // 3. 画面をリセット
      hideConfirmationDialog();
      container.querySelector('#resume-form').classList.add('hidden');
      container.querySelector('#resume-reason-select').value = '';
      container.querySelector('#resume-reason-detail').value = '';

      // 4. 一覧を再読み込み
      loadData();

      alert('作業を再開しました');

    } catch (error) {
      console.error('作業再開エラー:', error);
      showError('作業再開に失敗しました');
    }
  }

  // データ読み込み
  async function loadData() {
    try {
      const [workRecords, suspendRecords] = await Promise.all([
        window.aivicApi.list(1), // 作業記録
        window.aivicApi.list(2)  // 中断記録
      ]);

      renderSuspendedWorks(workRecords || [], suspendRecords || []);
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      renderSuspendedWorks([], []);
    }
  }

  // 文字数カウント更新
  function updateCharCount() {
    const textarea = container.querySelector('#resume-reason-detail');
    const countSpan = container.querySelector('#reason-char-count');
    countSpan.textContent = textarea.value.length;
  }

  // イベントリスナー設定

  // 戻るボタン
  container.querySelector('#btn-back').addEventListener('click', () => {
    window.showScreen('scr-1778907296658'); // 工数入力画面
  });

  // 再開ボタンクリック（行レベル）
  container.addEventListener('click', async (e) => {
    const resumeBtn = e.target.closest('.resume-btn');
    if (resumeBtn) {
      const workId = resumeBtn.dataset.workId;
      const suspendId = resumeBtn.dataset.suspendId;

      try {
        const [workRecords, suspendRecords] = await Promise.all([
          window.aivicApi.list(1),
          window.aivicApi.list(2)
        ]);

        const workRecord = workRecords.find(w => w.作業記録ID === workId);
        const suspendRecord = suspendRecords.find(s => s.中断記録ID === suspendId);

        if (workRecord) {
          showResumeForm(workRecord, suspendRecord);
        }
      } catch (error) {
        console.error('作業データ取得エラー:', error);
        showError('作業データの取得に失敗しました');
      }
    }
  });

  // 再開理由選択時の詳細フィールド連動
  container.querySelector('#resume-reason-select').addEventListener('change', (e) => {
    const detailField = container.querySelector('#resume-reason-detail');
    if (e.target.value && e.target.value !== 'その他') {
      detailField.value = e.target.value;
      updateCharCount();
    }
  });

  // 文字数カウント
  container.querySelector('#resume-reason-detail').addEventListener('input', updateCharCount);

  // キャンセルボタン
  container.querySelector('#btn-cancel-resume').addEventListener('click', () => {
    container.querySelector('#resume-form').classList.add('hidden');
    selectedWorkRecord = null;
    selectedSuspendRecord = null;
  });

  // 作業再開ボタン
  container.querySelector('#btn-confirm-resume').addEventListener('click', showConfirmationDialog);

  // ダイアログのキャンセル
  container.querySelector('#btn-dialog-cancel').addEventListener('click', hideConfirmationDialog);

  // ダイアログのOK
  container.querySelector('#btn-dialog-ok').addEventListener('click', resumeWork);

  // 初期データ読み込み
  loadData();
}

function(container, apiUrl, tables) {
  // エラー情報の初期化
  let errorInfo = {
    title: 'システムエラーが発生しました',
    message: '申し訳ございません。システムで予期しないエラーが発生しました。しばらく時間をおいて再度お試しください。',
    code: 'E001',
    time: new Date().toLocaleString('ja-JP', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    }).replace(/\//g, '/'),
    stack: 'TypeError: Cannot read property of undefined\n  at handleSubmit (app.js:123:45)\n  at HTMLButtonElement.<anonymous> (app.js:89:12)',
    previousScreen: 'scr-1778907133295', // 工数記録画面
    retryCount: 0
  };

  // URL パラメータからエラー情報を取得
  const urlParams = new URLSearchParams(window.location.search);
  if (urlParams.get('error')) {
    try {
      const errorData = JSON.parse(decodeURIComponent(urlParams.get('error')));
      errorInfo = { ...errorInfo, ...errorData };
    } catch (e) {
      console.warn('エラー情報の解析に失敗:', e);
    }
  }

  // エラー情報を画面に反映
  function updateErrorDisplay() {
    container.querySelector('#error-title').textContent = errorInfo.title;
    container.querySelector('#error-message').textContent = errorInfo.message;
    container.querySelector('#error-code').textContent = errorInfo.code;
    container.querySelector('#error-time').textContent = errorInfo.time;
    container.querySelector('#error-stack').textContent = errorInfo.stack;
  }

  // 詳細表示の切り替え
  function toggleErrorDetails() {
    const detailContent = container.querySelector('#error-detail-content');
    const toggleBtn = container.querySelector('#btn-toggle-details');
    const isHidden = detailContent.classList.contains('hidden');

    if (isHidden) {
      detailContent.classList.remove('hidden');
      toggleBtn.textContent = 'エラー詳細を非表示';

      // 詳細情報が取得できない場合のシミュレーション
      if (Math.random() < 0.1) {
        container.querySelector('#error-stack').textContent = 'エラーの詳細情報を取得できませんでした';
      }
    } else {
      detailContent.classList.add('hidden');
      toggleBtn.textContent = 'エラー詳細を表示';
    }
  }

  // 再試行処理
  async function handleRetry() {
    const retryBtn = container.querySelector('#btn-retry');
    const retryStatus = container.querySelector('#retry-status');

    // ボタンを無効化
    retryBtn.disabled = true;
    retryBtn.textContent = '再試行中...';

    try {
      // ネットワーク接続チェック（シミュレーション）
      const isOnline = navigator.onLine;

      if (!isOnline || errorInfo.retryCount >= 2) {
        // 再試行失敗
        retryStatus.classList.remove('hidden');
        retryBtn.textContent = '再試行';
        retryBtn.disabled = false;
        errorInfo.retryCount++;
        return;
      }

      // セッション切れチェック
      const sessionValid = localStorage.getItem('userSession');
      if (!sessionValid) {
        window.showScreen('scr-1778907121272'); // ログイン画面
        return;
      }

      // 成功時は前の画面に戻る
      setTimeout(() => {
        window.showScreen(errorInfo.previousScreen);
      }, 1000);

    } catch (error) {
      retryStatus.classList.remove('hidden');
      retryBtn.textContent = '再試行';
      retryBtn.disabled = false;
    }
  }

  // 戻る処理
  function handleBack() {
    if (window.history.length > 1) {
      window.history.back();
    } else {
      window.showScreen(errorInfo.previousScreen);
    }
  }

  // ホームに戻る処理
  function handleHome() {
    window.showScreen('scr-1778907133295'); // 工数記録画面
  }

  // 管理者連絡処理
  function handleContact() {
    const contactError = container.querySelector('#contact-error');

    // 連絡機能エラーのシミュレーション
    if (Math.random() < 0.3) {
      contactError.classList.remove('hidden');
      return;
    }

    // 緊急報告画面に遷移
    window.showScreen('scr-1778907330826');
  }

  // 長いエラーメッセージの制限
  function limitErrorMessage() {
    const messageEl = container.querySelector('#error-message');
    const message = messageEl.textContent;

    if (message.length > 500) {
      messageEl.textContent = message.substring(0, 497) + '...';
    }
  }

  // イベントリスナーの設定
  container.querySelector('#btn-toggle-details').addEventListener('click', toggleErrorDetails);
  container.querySelector('#btn-retry').addEventListener('click', handleRetry);
  container.querySelector('#btn-back').addEventListener('click', handleBack);
  container.querySelector('#btn-home').addEventListener('click', handleHome);
  container.querySelector('#btn-contact').addEventListener('click', handleContact);

  // 連続クリック防止
  let isProcessing = false;
  container.addEventListener('click', (e) => {
    if (e.target.matches('button') && isProcessing) {
      e.preventDefault();
      e.stopPropagation();
      return false;
    }

    if (e.target.matches('#btn-retry, #btn-back, #btn-home, #btn-contact')) {
      isProcessing = true;
      setTimeout(() => {
        isProcessing = false;
      }, 1000);
    }
  });

  // ネットワーク状態の監視
  window.addEventListener('online', () => {
    container.querySelector('#retry-status').classList.add('hidden');
  });

  window.addEventListener('offline', () => {
    const retryStatus = container.querySelector('#retry-status');
    retryStatus.querySelector('span').textContent = 'ネットワーク接続が切断されました。';
    retryStatus.classList.remove('hidden');
  });

  // 初期化
  updateErrorDisplay();
  limitErrorMessage();

  // 対処方法を表示
  container.querySelector('#error-solution').classList.remove('hidden');
}

function(container, apiUrl, tables) {
  let interruptions = [];

  // 現在のユーザー情報を設定
  const currentUser = { id: 'user-001', name: '田中太郎' };
  container.querySelector('#worker-name').value = currentUser.name;

  // 作業項目マスタの読み込み
  function loadWorkItems() {
    const workItemSelect = container.querySelector('#work-item');
    const workItemsTable = tables.find(t => t.tableName === '作業項目マスタ');
    if (workItemsTable && workItemsTable.records) {
      workItemsTable.records.forEach(item => {
        const option = document.createElement('option');
        option.value = item.作業項目ID;
        option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
        workItemSelect.appendChild(option);
      });
    }
  }

  // 実働時間の計算
  function calculateWorkTime() {
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = parseInt(container.querySelector('#break-time').value) || 0;

    if (!startTime || !endTime) {
      container.querySelector('#actual-work-time').value = '';
      return;
    }

    const start = new Date(`2000-01-01 ${startTime}`);
    let end = new Date(`2000-01-01 ${endTime}`);

    // 24時間をまたぐ場合
    if (end <= start) {
      end.setDate(end.getDate() + 1);
    }

    const diffMs = end.getTime() - start.getTime();
    const totalMinutes = Math.floor(diffMs / (1000 * 60));
    const actualMinutes = totalMinutes - breakTime;

    if (actualMinutes < 0) {
      container.querySelector('#actual-work-time').value = '';
      return;
    }

    const hours = Math.floor(actualMinutes / 60);
    const minutes = actualMinutes % 60;
    container.querySelector('#actual-work-time').value = `${hours}時間${minutes.toString().padStart(2, '0')}分`;
  }

  // 文字数カウント
  function updateCharCount() {
    const textarea = container.querySelector('#work-details');
    const charCount = container.querySelector('#char-count');
    charCount.textContent = textarea.value.length;
  }

  // 中断記録の描画
  function renderInterruptions() {
    const tbody = container.querySelector('#interruption-tbody');
    tbody.innerHTML = interruptions.map((int, index) => {
      const duration = int.終了時刻 ? calculateInterruptionDuration(int.開始時刻, int.終了時刻) : '進行中';
      return `
        <tr>
          <td style="padding: 6px 10px; color: var(--text);">${int.理由}</td>
          <td style="padding: 6px 10px; color: var(--text);">${int.開始時刻}</td>
          <td style="padding: 6px 10px; color: var(--text);">${int.終了時刻 || '-'}</td>
          <td style="padding: 6px 10px; color: var(--text);">${duration}</td>
          <td style="padding: 6px 10px; text-align: center;">
            <button class="delete-interruption" data-index="${index}" style="background: transparent; color: #ef4444; border: 1px solid rgba(239, 68, 68, 0.3); padding: 2px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">削除</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 中断時間の計算
  function calculateInterruptionDuration(start, end) {
    if (!start || !end) return '';
    const startTime = new Date(`2000-01-01 ${start}`);
    let endTime = new Date(`2000-01-01 ${end}`);

    if (endTime <= startTime) {
      endTime.setDate(endTime.getDate() + 1);
    }

    const diffMs = endTime.getTime() - startTime.getTime();
    const minutes = Math.floor(diffMs / (1000 * 60));
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;

    return `${hours}時間${mins.toString().padStart(2, '0')}分`;
  }

  // バリデーション
  function validateForm() {
    const errors = [];
    const workDate = container.querySelector('#work-date').value;
    const workItem = container.querySelector('#work-item').value;
    const workLocation = container.querySelector('#work-location').value;
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = parseInt(container.querySelector('#break-time').value) || 0;
    const workDetails = container.querySelector('#work-details').value;

    // 必須項目チェック
    if (!workDate) errors.push('作業日付は必須です');
    if (!workItem) errors.push('作業項目は必須です');
    if (!workLocation) errors.push('作業場所は必須です');
    if (!startTime) errors.push('開始時刻は必須です');
    if (!endTime) errors.push('終了時刻は必須です');
    if (!workDetails) errors.push('作業内容詳細は必須です');

    // 未来日付チェック
    if (workDate) {
      const today = new Date();
      const selectedDate = new Date(workDate);
      today.setHours(0, 0, 0, 0);
      selectedDate.setHours(0, 0, 0, 0);
      if (selectedDate > today) {
        errors.push('未来の日付は選択できません');
      }
    }

    // 時刻フォーマットチェック
    const timePattern = /^([01]?[0-9]|2[0-3]):[0-5][0-9]$/;
    if (startTime && !timePattern.test(startTime)) {
      errors.push('開始時刻の形式が正しくありません');
    }
    if (endTime && !timePattern.test(endTime)) {
      errors.push('終了時刻の形式が正しくありません');
    }

    // 開始終了時刻の関係チェック
    if (startTime && endTime) {
      if (startTime === endTime) {
        errors.push('開始時刻と終了時刻が同じです');
      }

      // 実働時間と休憩時間の関係チェック
      const start = new Date(`2000-01-01 ${startTime}`);
      let end = new Date(`2000-01-01 ${endTime}`);

      if (end <= start) {
        end.setDate(end.getDate() + 1);
      }

      const totalMinutes = Math.floor((end.getTime() - start.getTime()) / (1000 * 60));
      if (breakTime > totalMinutes) {
        errors.push('休憩時間が実働時間を超過しています');
      }
    }

    // 文字数チェック
    if (workDetails.length > 500) {
      errors.push('作業内容詳細は500文字以内で入力してください');
    }

    return errors;
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
    setTimeout(() => {
      errorDiv.style.display = 'none';
    }, 5000);
  }

  // 初期化
  loadWorkItems();
  container.querySelector('#work-date').value = new Date().toISOString().split('T')[0];

  // イベントリスナー
  container.querySelector('#start-time').addEventListener('change', calculateWorkTime);
  container.querySelector('#end-time').addEventListener('change', calculateWorkTime);
  container.querySelector('#break-time').addEventListener('input', calculateWorkTime);
  container.querySelector('#work-details').addEventListener('input', updateCharCount);

  // 進捗状況変更で中断セクション表示切り替え
  container.querySelector('#progress-status').addEventListener('change', function() {
    const interruptionSection = container.querySelector('#interruption-section');
    if (this.value === '中断') {
      interruptionSection.style.display = 'block';
    } else {
      interruptionSection.style.display = 'none';
    }
  });

  // 中断記録追加
  container.querySelector('#add-interruption').addEventListener('click', function() {
    const reason = container.querySelector('#interruption-reason').value;
    const startTime = container.querySelector('#interruption-start').value;
    const endTime = container.querySelector('#interruption-end').value;

    if (!reason || !startTime) {
      showError('中断理由と開始時刻は必須です');
      return;
    }

    interruptions.push({
      理由: reason,
      開始時刻: startTime,
      終了時刻: endTime
    });

    renderInterruptions();

    // フォームクリア
    container.querySelector('#interruption-reason').value = '';
    container.querySelector('#interruption-start').value = '';
    container.querySelector('#interruption-end').value = '';
  });

  // 中断記録削除
  container.addEventListener('click', function(e) {
    if (e.target.classList.contains('delete-interruption')) {
      const index = parseInt(e.target.dataset.index);
      interruptions.splice(index, 1);
      renderInterruptions();
    }
  });

  // 作業中断ボタン
  container.querySelector('#btn-interruption').addEventListener('click', function() {
    window.showScreen("scr-1778907238439");
  });

  // 作業終了ボタン
  container.querySelector('#btn-finish').addEventListener('click', function() {
    window.showScreen("scr-1778907199709");
  });

  // 登録ボタン
  container.querySelector('#btn-save').addEventListener('click', async function() {
    const errors = validateForm();
    if (errors.length > 0) {
      showError(errors.join('、'));
      return;
    }

    const workData = {
      作業員ID: currentUser.id,
      作業日: container.querySelector('#work-date').value,
      作業開始時刻: `${container.querySelector('#work-date').value} ${container.querySelector('#start-time').value}:00`,
      作業終了時刻: `${container.querySelector('#work-date').value} ${container.querySelector('#end-time').value}:00`,
      プロジェクト名: container.querySelector('#work-item').selectedOptions[0]?.textContent || '',
      作業場所: container.querySelector('#work-location').value,
      作業種別: container.querySelector('#work-item').selectedOptions[0]?.textContent?.split(' - ')[1] || '',
      作業内容: container.querySelector('#work-details').value,
      進捗状況: container.querySelector('#progress-status').value,
      承認状態: '未承認',
      作成者ID: currentUser.id
    };

    // 実働時間を分で計算
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = parseInt(container.querySelector('#break-time').value) || 0;

    if (startTime && endTime) {
      const start = new Date(`2000-01-01 ${startTime}`);
      let end = new Date(`2000-01-01 ${endTime}`);

      if (end <= start) {
        end.setDate(end.getDate() + 1);
      }

      const totalMinutes = Math.floor((end.getTime() - start.getTime()) / (1000 * 60));
      workData.作業時間 = totalMinutes - breakTime;
    }

    try {
      const workRecordsTableIndex = tables.findIndex(t => t.tableName === '作業記録');
      const saved = await window.aivicApi.save(workRecordsTableIndex, workData);

      if (saved) {
        // 中断記録も保存
        if (interruptions.length > 0) {
          const interruptionTableIndex = tables.findIndex(t => t.tableName === '中断記録');
          for (const interruption of interruptions) {
            await window.aivicApi.save(interruptionTableIndex, {
              作業記録ID: saved.作業記録ID,
              中断開始日時: `${container.querySelector('#work-date').value} ${interruption.開始時刻}:00`,
              中断終了日時: interruption.終了時刻 ? `${container.querySelector('#work-date').value} ${interruption.終了時刻}:00` : null,
              中断理由区分: interruption.理由,
              対応状況: '未対応',
              記録者ID: currentUser.id
            });
          }
        }

        alert('工数記録が正常に登録されました');

        // フォームリセット
        container.querySelector('#work-record-form').reset();
        container.querySelector('#worker-name').value = currentUser.name;
        container.querySelector('#work-date').value = new Date().toISOString().split('T')[0];
        container.querySelector('#actual-work-time').value = '';
        container.querySelector('#char-count').textContent = '0';
        interruptions = [];
        renderInterruptions();
        container.querySelector('#interruption-section').style.display = 'none';
      }
    } catch (error) {
      showError('登録に失敗しました');
    }
  });
}

function(container, apiUrl, tables) {
  let workRecords = [];
  let breakRecords = [];
  let workItems = [];
  let selectedRecordId = null;
  let originalData = null;

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      workRecords = await window.aivicApi.list(1) || tables[1]?.records || [];
      breakRecords = await window.aivicApi.list(2) || tables[2]?.records || [];
      workItems = await window.aivicApi.list(3) || tables[3]?.records || [];

      populateTargetRecords();
      populateWorkItems();
    } catch (error) {
      console.error('データ読み込みエラー:', error);
    }
  }

  // 修正対象記録のドロップダウンを設定
  function populateTargetRecords() {
    const targetSelect = container.querySelector('#target-record');
    targetSelect.innerHTML = '<option value="">選択してください</option>';

    workRecords.forEach(record => {
      const option = document.createElement('option');
      option.value = record.id || record.作業記録ID;
      const workDate = new Date(record.作業日 || record.workDate).toLocaleDateString('ja-JP');
      const projectName = record.プロジェクト名 || record.projectName || '';
      const workType = record.作業種別 || record.workType || '';
      option.textContent = `${workDate} - ${projectName} - ${workType}`;
      targetSelect.appendChild(option);
    });
  }

  // 作業項目のドロップダウンを設定
  function populateWorkItems() {
    const workItemSelect = container.querySelector('#work-item');
    workItemSelect.innerHTML = '<option value="">選択してください</option>';

    workItems.forEach(item => {
      const option = document.createElement('option');
      option.value = item.id || item.作業項目ID;
      option.textContent = `${item.作業項目コード || item.code || ''} - ${item.作業項目名 || item.name || ''}`;
      workItemSelect.appendChild(option);
    });
  }

  // 修正対象記録選択時の処理
  container.querySelector('#target-record').addEventListener('change', function() {
    selectedRecordId = this.value;
    if (selectedRecordId) {
      const record = workRecords.find(r => (r.id || r.作業記録ID) === selectedRecordId);
      if (record) {
        originalData = { ...record };
        displayOriginalData(record);
        populateFormWithRecord(record);
        calculateTimes();
      }
    } else {
      hideOriginalData();
      clearForm();
    }
  });

  // 修正前データ表示
  function displayOriginalData(record) {
    const originalDataDiv = container.querySelector('#original-data');
    const contentDiv = container.querySelector('#original-data-content');

    const workDate = new Date(record.作業日 || record.workDate).toLocaleDateString('ja-JP');
    const startTime = formatTime(record.作業開始時刻 || record.startTime);
    const endTime = formatTime(record.作業終了時刻 || record.endTime);
    const projectName = record.プロジェクト名 || record.projectName || '';
    const workType = record.作業種別 || record.workType || '';

    contentDiv.innerHTML = `
      <div>作業日: ${workDate}</div>
      <div>開始時刻: ${startTime} / 終了時刻: ${endTime}</div>
      <div>プロジェクト: ${projectName} / 作業種別: ${workType}</div>
    `;

    originalDataDiv.style.display = 'block';
  }

  function hideOriginalData() {
    container.querySelector('#original-data').style.display = 'none';
  }

  // フォームに記録データを設定
  function populateFormWithRecord(record) {
    const workDate = new Date(record.作業日 || record.workDate);
    container.querySelector('#work-date').value = workDate.toISOString().split('T')[0];

    container.querySelector('#start-time').value = formatTimeForInput(record.作業開始時刻 || record.startTime);
    container.querySelector('#end-time').value = formatTimeForInput(record.作業終了時刻 || record.endTime);

    // 中断記録があれば設定
    const breakRecord = breakRecords.find(br => (br.作業記録ID || br.workRecordId) === selectedRecordId);
    if (breakRecord) {
      container.querySelector('#break-time').value = formatTimeForInput(breakRecord.中断開始日時 || breakRecord.startTime);
      container.querySelector('#break-reason').value = breakRecord.中断理由区分 || breakRecord.reason || '';
    }
  }

  function clearForm() {
    container.querySelector('#work-date').value = '';
    container.querySelector('#start-time').value = '';
    container.querySelector('#end-time').value = '';
    container.querySelector('#work-item').value = '';
    container.querySelector('#break-time').value = '';
    container.querySelector('#break-reason').value = '';
    container.querySelector('#correction-reason').value = '';
    hideWarnings();
    hideErrors();
  }

  // 時刻フォーマット関数
  function formatTime(timeStr) {
    if (!timeStr) return '';
    const date = new Date(timeStr);
    return date.toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
  }

  function formatTimeForInput(timeStr) {
    if (!timeStr) return '';
    const date = new Date(timeStr);
    return date.toTimeString().slice(0, 5);
  }

  // 時間計算
  function calculateTimes() {
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = container.querySelector('#break-time').value;

    if (startTime && endTime) {
      const start = new Date(`2000-01-01T${startTime}`);
      const end = new Date(`2000-01-01T${endTime}`);

      if (end > start) {
        const totalMinutes = (end - start) / (1000 * 60);
        let breakMinutes = 0;

        if (breakTime) {
          const breakStart = new Date(`2000-01-01T${breakTime}`);
          if (breakStart >= start && breakStart <= end) {
            // 簡単な中断時間計算（1時間と仮定）
            breakMinutes = 60;
          }
        }

        const actualMinutes = totalMinutes - breakMinutes;
        const hours = Math.floor(actualMinutes / 60);
        const minutes = actualMinutes % 60;

        container.querySelector('#break-duration').textContent = `${breakMinutes}分`;
        container.querySelector('#actual-work-time').textContent = `${hours}時間${minutes}分`;

        // 異常値チェック
        checkAbnormalValues(actualMinutes, totalMinutes);
      }
    }
  }

  // 異常値チェック
  function checkAbnormalValues(actualMinutes, totalMinutes) {
    const warnings = [];

    // 24時間を超える作業
    if (totalMinutes > 24 * 60) {
      warnings.push('作業時間が24時間を超えています');
    }

    // 16時間を超える作業
    if (actualMinutes > 16 * 60) {
      warnings.push('実作業時間が16時間を超えています（長時間作業）');
    }

    // 負の作業時間
    if (actualMinutes < 0) {
      warnings.push('作業時間が負の値になっています');
    }

    if (warnings.length > 0) {
      showWarnings(warnings);
    } else {
      hideWarnings();
    }
  }

  function showWarnings(warnings) {
    const warningArea = container.querySelector('#warning-area');
    const messagesDiv = container.querySelector('#warning-messages');
    messagesDiv.innerHTML = warnings.map(w => `<div>• ${w}</div>`).join('');
    warningArea.style.display = 'block';
  }

  function hideWarnings() {
    container.querySelector('#warning-area').style.display = 'none';
  }

  function showErrors(errors) {
    const errorArea = container.querySelector('#error-area');
    const messagesDiv = container.querySelector('#error-messages');
    messagesDiv.innerHTML = errors.map(e => `<div>• ${e}</div>`).join('');
    errorArea.style.display = 'block';
  }

  function hideErrors() {
    container.querySelector('#error-area').style.display = 'none';
  }

  // バリデーション
  function validateForm() {
    const errors = [];

    if (!selectedRecordId) {
      errors.push('修正対象記録を選択してください');
    }

    const correctionReason = container.querySelector('#correction-reason').value.trim();
    if (!correctionReason) {
      errors.push('修正理由を入力してください');
    }

    if (correctionReason.length > 200) {
      errors.push('修正理由は200文字以内で入力してください');
    }

    const workDate = container.querySelector('#work-date').value;
    if (workDate) {
      const date = new Date(workDate);
      const minDate = new Date('1900-01-01');
      const maxDate = new Date('2099-12-31');
      if (date < minDate || date > maxDate) {
        errors.push('作業日付は1900年1月1日から2099年12月31日の範囲で入力してください');
      }
    }

    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    if (startTime && endTime) {
      const start = new Date(`2000-01-01T${startTime}`);
      const end = new Date(`2000-01-01T${endTime}`);
      if (start >= end) {
        errors.push('開始時刻は終了時刻より前の時刻を入力してください');
      }
    }

    const breakTime = container.querySelector('#break-time').value;
    if (breakTime && startTime && endTime) {
      const breakStart = new Date(`2000-01-01T${breakTime}`);
      const start = new Date(`2000-01-01T${startTime}`);
      const end = new Date(`2000-01-01T${endTime}`);
      if (breakStart < start || breakStart > end) {
        errors.push('中断時刻が作業時間外です');
      }
    }

    return errors;
  }

  // 時間変更時の再計算
  ['#start-time', '#end-time', '#break-time'].forEach(selector => {
    container.querySelector(selector).addEventListener('change', calculateTimes);
  });

  // 保存ボタン
  container.querySelector('#btn-save').addEventListener('click', async function() {
    hideErrors();

    const errors = validateForm();
    if (errors.length > 0) {
      showErrors(errors);
      return;
    }

    try {
      const updateData = {
        作業日: container.querySelector('#work-date').value,
        作業開始時刻: container.querySelector('#start-time').value ? `2000-01-01T${container.querySelector('#start-time').value}` : null,
        作業終了時刻: container.querySelector('#end-time').value ? `2000-01-01T${container.querySelector('#end-time').value}` : null,
        更新日時: new Date().toISOString()
      };

      const result = await window.aivicApi.update(1, selectedRecordId, updateData);
      if (result) {
        // 中断記録も更新
        const breakTime = container.querySelector('#break-time').value;
        const breakReason = container.querySelector('#break-reason').value;
        if (breakTime && breakReason) {
          const breakRecord = breakRecords.find(br => (br.作業記録ID || br.workRecordId) === selectedRecordId);
          if (breakRecord) {
            await window.aivicApi.update(2, breakRecord.id || breakRecord.中断記録ID, {
              中断開始日時: `2000-01-01T${breakTime}`,
              中断理由区分: breakReason,
              更新日時: new Date().toISOString()
            });
          }
        }

        alert('修正が完了しました');
        window.showScreen('scr-1778907145716'); // 作業履歴一覧画面
      }
    } catch (error) {
      showErrors(['保存に失敗しました']);
    }
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', function() {
    window.showScreen('scr-1778907145716'); // 作業履歴一覧画面
  });

  // 初期データ読み込み実行
  loadInitialData();
}

function(container, apiUrl, tables) {
  let attachedFiles = [];
  let currentDraftId = null;

  // 現在のユーザー情報を設定
  const reporterNameInput = container.querySelector('#reporter-name');
  reporterNameInput.value = '田中太郎'; // 実際の実装では認証情報から取得

  // 作業項目マスタの読み込み
  const workItemSelect = container.querySelector('#work-item');
  if (tables[3] && tables[3].records) {
    tables[3].records.forEach(item => {
      const option = document.createElement('option');
      option.value = item.作業項目ID;
      option.textContent = item.作業項目名;
      workItemSelect.appendChild(option);
    });
  }

  // 文字数カウンター
  const emergencyContent = container.querySelector('#emergency-content');
  const charCount = container.querySelector('#char-count');
  emergencyContent.addEventListener('input', () => {
    const count = emergencyContent.value.length;
