    if (count > 1000) {
      charCount.style.color = '#dc3545';
    } else {
      charCount.style.color = 'var(--text-muted)';
    }
  });

  // 写真添付機能
  const photoInput = container.querySelector('#photo-input');
  const photoSelectBtn = container.querySelector('#btn-photo-select');
  const photoDropZone = container.querySelector('#photo-drop-zone');
  const photoPreview = container.querySelector('#photo-preview');

  photoSelectBtn.addEventListener('click', () => {
    photoInput.click();
  });

  photoInput.addEventListener('change', handleFileSelect);

  // ドラッグ&ドロップ
  photoDropZone.addEventListener('dragover', (e) => {
    e.preventDefault();
    photoDropZone.style.borderColor = 'var(--primary)';
    photoDropZone.style.background = 'rgba(255,255,255,0.05)';
  });

  photoDropZone.addEventListener('dragleave', (e) => {
    e.preventDefault();
    photoDropZone.style.borderColor = 'rgba(255,255,255,0.18)';
    photoDropZone.style.background = 'rgba(0,0,0,0.1)';
  });

  photoDropZone.addEventListener('drop', (e) => {
    e.preventDefault();
    photoDropZone.style.borderColor = 'rgba(255,255,255,0.18)';
    photoDropZone.style.background = 'rgba(0,0,0,0.1)';

    const files = Array.from(e.dataTransfer.files);
    handleFileSelect({ target: { files } });
  });

  function handleFileSelect(e) {
    const files = Array.from(e.target.files);
    const errorDiv = container.querySelector('#error-photo');

    // ファイル数チェック
    if (attachedFiles.length + files.length > 5) {
      showError('error-photo', '添付できる写真は最大5枚までです。');
      return;
    }

    files.forEach(file => {
      // ファイル形式チェック
      if (!file.type.startsWith('image/')) {
        showError('error-photo', 'サポートされていないファイル形式です。画像ファイルを選択してください。');
        return;
      }

      // ファイルサイズチェック（10MB）
      if (file.size > 10 * 1024 * 1024) {
        showError('error-photo', 'ファイルサイズは10MB以下にしてください。');
        return;
      }

      attachedFiles.push(file);
      addPhotoPreview(file);
    });

    hideError('error-photo');
  }

  function addPhotoPreview(file) {
    const reader = new FileReader();
    reader.onload = (e) => {
      const previewItem = document.createElement('div');
      previewItem.style.cssText = 'position: relative; border-radius: 6px; overflow: hidden; background: var(--bg-card);';

      previewItem.innerHTML = `
        <img src="${e.target.result}" style="width: 100%; height: 80px; object-fit: cover;">
        <button type="button" class="remove-photo" data-filename="${file.name}" style="position: absolute; top: 4px; right: 4px; width: 20px; height: 20px; border: none; border-radius: 50%; background: rgba(220,53,69,0.9); color: #fff; font-size: 12px; cursor: pointer; display: flex; align-items: center; justify-content: center;">×</button>
        <div style="padding: 4px; font-size: 10px; color: var(--text-muted); text-overflow: ellipsis; overflow: hidden; white-space: nowrap;">${file.name}</div>
      `;

      photoPreview.appendChild(previewItem);
    };
    reader.readAsDataURL(file);
  }

  // 写真削除
  photoPreview.addEventListener('click', (e) => {
    const removeBtn = e.target.closest('.remove-photo');
    if (removeBtn) {
      const filename = removeBtn.dataset.filename;
      attachedFiles = attachedFiles.filter(f => f.name !== filename);
      removeBtn.closest('div').remove();
    }
  });

  // バリデーション関数
  function validateForm() {
    let isValid = true;

    // 緊急度チェック
    const urgency = container.querySelector('input[name="urgency"]:checked');
    if (!urgency) {
      showError('error-urgency', '緊急度を選択してください。');
      isValid = false;
    } else {
      hideError('error-urgency');
    }

    // 報告種別チェック
    const reportType = container.querySelector('#report-type').value;
    if (!reportType) {
      showError('error-report-type', '報告種別を選択してください。');
      isValid = false;
    } else {
      hideError('error-report-type');
    }

    // 発生日時チェック
    const occurrenceDateTime = container.querySelector('#occurrence-datetime').value;
    if (!occurrenceDateTime) {
      showError('error-occurrence-datetime', '発生日時を入力してください。');
      isValid = false;
    } else {
      const selectedDate = new Date(occurrenceDateTime);
      const now = new Date();
      if (selectedDate > now) {
        showError('error-occurrence-datetime', '発生日時に未来の日付は入力できません。');
        isValid = false;
      } else {
        hideError('error-occurrence-datetime');
      }
    }

    // 発生場所チェック
    const location = container.querySelector('#location').value.trim();
    if (!location) {
      showError('error-location', '発生場所を入力してください。');
      isValid = false;
    } else {
      hideError('error-location');
    }

    // 緊急事態内容チェック
    const emergencyContent = container.querySelector('#emergency-content').value.trim();
    if (!emergencyContent) {
      showError('error-emergency-content', '緊急事態内容を入力してください。');
      isValid = false;
    } else if (emergencyContent.length > 1000) {
      showError('error-emergency-content', '文字数上限を超えています。');
      isValid = false;
    } else {
      hideError('error-emergency-content');
    }

    // 連絡先電話番号チェック
    const contactPhone = container.querySelector('#contact-phone').value.trim();
    if (!contactPhone) {
      showError('error-contact-phone', '連絡先電話番号を入力してください。');
      isValid = false;
    } else {
      const phonePattern = /^(\d{2,4}-\d{2,4}-\d{4}|\d{10,11})$/;
      if (!phonePattern.test(contactPhone.replace(/-/g, ''))) {
        showError('error-contact-phone', '正しい電話番号の形式で入力してください。');
        isValid = false;
      } else {
        hideError('error-contact-phone');
      }
    }

    return isValid;
  }

  function showError(errorId, message) {
    const errorDiv = container.querySelector(`#${errorId}`);
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
  }

  function hideError(errorId) {
    const errorDiv = container.querySelector(`#${errorId}`);
    errorDiv.style.display = 'none';
  }

  // フォームデータ収集
  function collectFormData() {
    const urgency = container.querySelector('input[name="urgency"]:checked');
    return {
      緊急度: urgency ? urgency.value : '',
      報告種別: container.querySelector('#report-type').value,
      発生日時: container.querySelector('#occurrence-datetime').value,
      発生場所: container.querySelector('#location').value.trim(),
      作業項目ID: container.querySelector('#work-item').value,
      緊急事態内容: container.querySelector('#emergency-content').value.trim(),
      報告者名: container.querySelector('#reporter-name').value,
      連絡先電話番号: container.querySelector('#contact-phone').value.trim(),
      添付ファイル数: attachedFiles.length,
      報告日時: new Date().toISOString(),
      状態: '未対応'
    };
  }

  // 下書き保存
  container.querySelector('#btn-draft-save').addEventListener('click', async () => {
    const formData = collectFormData();
    formData.状態 = '下書き';

    try {
      let result;
      if (currentDraftId) {
        result = await window.aivicApi.update(4, currentDraftId, formData);
      } else {
        result = await window.aivicApi.save(4, formData);
        if (result) {
          currentDraftId = result.id;
        }
      }

      if (result) {
        container.querySelector('#draft-success-message').style.display = 'block';
        setTimeout(() => {
          container.querySelector('#draft-success-message').style.display = 'none';
        }, 3000);
      }
    } catch (error) {
      console.error('下書き保存エラー:', error);
    }
  });

  // 緊急報告送信
  container.querySelector('#btn-submit').addEventListener('click', async () => {
    if (!validateForm()) {
      return;
    }

    const formData = collectFormData();
    formData.状態 = '送信済み';

    try {
      const result = await window.aivicApi.save(4, formData);
      if (result) {
        container.querySelector('#success-message').style.display = 'block';
        container.querySelector('#completion-actions').style.display = 'block';
        container.querySelector('#emergency-form').style.display = 'none';
        container.querySelector('#btn-draft-save').style.display = 'none';
        container.querySelector('#btn-submit').style.display = 'none';
      }
    } catch (error) {
      console.error('送信エラー:', error);
    }
  });

  // 報告完了ボタン
  container.querySelector('#btn-complete').addEventListener('click', () => {
    window.showScreen("scr-1778907133295");
  });

  // 現在日時を発生日時のデフォルト値に設定
  const now = new Date();
  const localDateTime = new Date(now.getTime() - now.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
  container.querySelector('#occurrence-datetime').value = localDateTime;

  // 下書きデータの復元（実際の実装では localStorage や API から取得）
  // 今回はサンプルとして空の状態から開始
}

function(container, apiUrl, tables) {
  let currentRecord = null;
  let originalData = null;
  let workItems = [];

  // 作業項目マスタを取得
  async function loadWorkItems() {
    const items = await window.aivicApi.list(3); // 作業項目マスタ
    if (items) {
      workItems = items.filter(item => item.有効フラグ);
      const workItemSelect = container.querySelector('#work-item');
      workItemSelect.innerHTML = '<option value="">選択してください</option>';
      workItems.forEach(item => {
        workItemSelect.innerHTML += `<option value="${item.作業項目ID}">${item.作業項目名}</option>`;
      });
    }
  }

  // 作業記録一覧を読み込み
  async function loadWorkRecords() {
    const records = await window.aivicApi.list(1); // 作業記録
    if (records) {
      const select = container.querySelector('#work-record-select');
      select.innerHTML = '<option value="">選択してください</option>';
      records.forEach(record => {
        const date = new Date(record.作業日).toLocaleDateString('ja-JP');
        const project = record.プロジェクト名 || '';
        const workType = record.作業種別 || '';
        select.innerHTML += `<option value="${record.作業記録ID}">${date} - ${project} - ${workType}</option>`;
      });
    }
  }

  // 時間計算
  function calculateTime() {
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = parseInt(container.querySelector('#break-time').value) || 0;

    if (!startTime || !endTime) {
      container.querySelector('#total-work-time').value = '';
      container.querySelector('#net-work-time').value = '';
      return;
    }

    const start = new Date(`2000-01-01T${startTime}`);
    let end = new Date(`2000-01-01T${endTime}`);

    // 24時間跨ぎの処理
    if (end <= start) {
      end.setDate(end.getDate() + 1);
    }

    const totalMinutes = (end - start) / (1000 * 60);
    const netMinutes = Math.max(0, totalMinutes - breakTime);

    const totalHours = Math.floor(totalMinutes / 60);
    const totalMins = totalMinutes % 60;
    const netHours = Math.floor(netMinutes / 60);
    const netMins = netMinutes % 60;

    container.querySelector('#total-work-time').value = `${totalHours}時間${totalMins}分`;
    container.querySelector('#net-work-time').value = `${netHours}時間${netMins}分`;

    validateInput();
  }

  // バリデーション
  function validateInput() {
    const errorArea = container.querySelector('#error-area');
    const warningArea = container.querySelector('#warning-area');
    const saveBtn = container.querySelector('#save-btn');

    errorArea.style.display = 'none';
    warningArea.style.display = 'none';

    const recordId = container.querySelector('#work-record-select').value;
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = parseInt(container.querySelector('#break-time').value) || 0;
    const reason = container.querySelector('#correction-reason').value.trim();

    // 必須チェック
    if (!recordId) {
      showError('修正対象の作業記録を選択してください');
      saveBtn.disabled = true;
      return;
    }

    if (!reason) {
      showError('修正理由を入力してください');
      saveBtn.disabled = true;
      return;
    }

    // 時刻チェック
    if (startTime && endTime) {
      const start = new Date(`2000-01-01T${startTime}`);
      let end = new Date(`2000-01-01T${endTime}`);

      if (end <= start && startTime === endTime) {
        showError('作業時間が0分です。開始時刻と終了時刻を確認してください。');
        saveBtn.disabled = true;
        return;
      }

      if (end <= start) {
        end.setDate(end.getDate() + 1);
      }

      const totalMinutes = (end - start) / (1000 * 60);

      // 中断時間チェック
      if (breakTime > totalMinutes) {
        showError('中断時間が作業時間を超過しています');
        saveBtn.disabled = true;
        return;
      }

      // 異常値警告
      if (totalMinutes > 12 * 60) { // 12時間超過
        showWarning('作業時間が12時間を超えています。確認してください。');
      }
    }

    saveBtn.disabled = false;
  }

  function showError(message) {
    const errorArea = container.querySelector('#error-area');
    const errorMessage = container.querySelector('#error-message');
    errorMessage.textContent = message;
    errorArea.style.display = 'block';
  }

  function showWarning(message) {
    const warningArea = container.querySelector('#warning-area');
    const warningMessage = container.querySelector('#warning-message');
    warningMessage.textContent = message;
    warningArea.style.display = 'block';
  }

  // 文字数カウント
  function updateCharCount(textareaId, countId) {
    const textarea = container.querySelector(`#${textareaId}`);
    const counter = container.querySelector(`#${countId}`);
    counter.textContent = textarea.value.length;
  }

  // 作業記録選択時の処理
  container.querySelector('#work-record-select').addEventListener('change', async function() {
    const recordId = this.value;
    if (!recordId) {
      currentRecord = null;
      originalData = null;
      clearForm();
      return;
    }

    const records = await window.aivicApi.list(1);
    if (records) {
      currentRecord = records.find(r => r.作業記録ID === recordId);
      originalData = { ...currentRecord };

      if (currentRecord) {
        // フォームに値を設定
        const workDate = new Date(currentRecord.作業日).toLocaleDateString('ja-JP');
        container.querySelector('#work-date').value = workDate;

        if (currentRecord.作業開始時刻) {
          const startTime = new Date(currentRecord.作業開始時刻);
          container.querySelector('#start-time').value = startTime.toTimeString().slice(0, 5);
        }

        if (currentRecord.作業終了時刻) {
          const endTime = new Date(currentRecord.作業終了時刻);
          container.querySelector('#end-time').value = endTime.toTimeString().slice(0, 5);
        }

        // 中断時間を取得
        const breakRecords = await window.aivicApi.list(2); // 中断記録
        if (breakRecords) {
          const totalBreakTime = breakRecords
            .filter(br => br.作業記録ID === recordId)
            .reduce((sum, br) => sum + (br.中断時間 || 0), 0);
          container.querySelector('#break-time').value = totalBreakTime;
        }

        container.querySelector('#work-item').value = currentRecord.作業項目ID || '';
        container.querySelector('#work-content').value = currentRecord.作業内容 || '';

        calculateTime();
        container.querySelector('#view-original-btn').disabled = false;
      }
    }
  });

  function clearForm() {
    container.querySelector('#work-date').value = '';
    container.querySelector('#start-time').value = '';
    container.querySelector('#end-time').value = '';
    container.querySelector('#break-time').value = '';
    container.querySelector('#total-work-time').value = '';
    container.querySelector('#net-work-time').value = '';
    container.querySelector('#work-item').value = '';
    container.querySelector('#work-content').value = '';
    container.querySelector('#correction-reason').value = '';
    container.querySelector('#view-original-btn').disabled = true;
    container.querySelector('#save-btn').disabled = true;
    container.querySelector('#error-area').style.display = 'none';
    container.querySelector('#warning-area').style.display = 'none';
    updateCharCount('work-content', 'content-count');
    updateCharCount('correction-reason', 'reason-count');
  }

  // イベントリスナー
  container.querySelector('#start-time').addEventListener('change', calculateTime);
  container.querySelector('#end-time').addEventListener('change', calculateTime);
  container.querySelector('#break-time').addEventListener('input', calculateTime);
  container.querySelector('#correction-reason').addEventListener('input', () => {
    updateCharCount('correction-reason', 'reason-count');
    validateInput();
  });
  container.querySelector('#work-content').addEventListener('input', () => {
    updateCharCount('work-content', 'content-count');
  });

  // 元データ参照
  container.querySelector('#view-original-btn').addEventListener('click', function() {
    if (!originalData) return;

    const modal = container.querySelector('#original-data-modal');
    const content = container.querySelector('#original-data-content');

    const startTime = originalData.作業開始時刻 ? new Date(originalData.作業開始時刻).toLocaleString('ja-JP') : '未設定';
    const endTime = originalData.作業終了時刻 ? new Date(originalData.作業終了時刻).toLocaleString('ja-JP') : '未設定';
    const workDate = new Date(originalData.作業日).toLocaleDateString('ja-JP');

    content.innerHTML = `
      <div style="margin-bottom: 12px;"><strong>作業日:</strong> ${workDate}</div>
      <div style="margin-bottom: 12px;"><strong>開始時刻:</strong> ${startTime}</div>
      <div style="margin-bottom: 12px;"><strong>終了時刻:</strong> ${endTime}</div>
      <div style="margin-bottom: 12px;"><strong>プロジェクト名:</strong> ${originalData.プロジェクト名 || ''}</div>
      <div style="margin-bottom: 12px;"><strong>作業種別:</strong> ${originalData.作業種別 || ''}</div>
      <div style="margin-bottom: 12px;"><strong>作業内容:</strong> ${originalData.作業内容 || ''}</div>
      <div style="margin-bottom: 12px;"><strong>進捗状況:</strong> ${originalData.進捗状況 || ''}</div>
    `;

    modal.style.display = 'block';
  });

  container.querySelector('#close-modal-btn').addEventListener('click', function() {
    container.querySelector('#original-data-modal').style.display = 'none';
  });

  // 保存処理
  container.querySelector('#save-btn').addEventListener('click', async function() {
    if (!currentRecord) return;

    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = parseInt(container.querySelector('#break-time').value) || 0;
    const workItemId = container.querySelector('#work-item').value;
    const workContent = container.querySelector('#work-content').value;
    const reason = container.querySelector('#correction-reason').value.trim();

    // 作業時間計算
    let workTimeMinutes = null;
    if (startTime && endTime) {
      const start = new Date(`2000-01-01T${startTime}`);
      let end = new Date(`2000-01-01T${endTime}`);
      if (end <= start) {
        end.setDate(end.getDate() + 1);
      }
      workTimeMinutes = Math.max(0, (end - start) / (1000 * 60) - breakTime);
    }

    const updateData = {
      作業開始時刻: startTime ? new Date(`${new Date(currentRecord.作業日).toISOString().split('T')[0]}T${startTime}`).toISOString() : currentRecord.作業開始時刻,
      作業終了時刻: endTime ? new Date(`${new Date(currentRecord.作業日).toISOString().split('T')[0]}T${endTime}`).toISOString() : currentRecord.作業終了時刻,
      作業時間: workTimeMinutes,
      作業項目ID: workItemId || currentRecord.作業項目ID,
      作業内容: workContent,
      更新日時: new Date().toISOString()
    };

    const updated = await window.aivicApi.update(1, currentRecord.作業記録ID, updateData);
    if (updated) {
      // 異常値検出ログの記録
      if (workTimeMinutes && workTimeMinutes > 12 * 60) {
        await window.aivicApi.save(4, {
          異常値検出ログID: crypto.randomUUID(),
          検出対象テーブル: '作業記録',
          検出対象レコードID: currentRecord.作業記録ID,
          ユーザーID: currentRecord.作業員ID,
          異常値種別: '長時間作業',
          検出項目: '作業時間',
          検出値: `${Math.floor(workTimeMinutes / 60)}時間${workTimeMinutes % 60}分`,
          閾値: '12時間',
          重要度: '中',
          確認状況: '未確認',
          通知送信フラグ: false,
          検出日時: new Date().toISOString(),
          作成日時: new Date().toISOString(),
          更新日時: new Date().toISOString()
        });
      }

      alert('工数修正が完了しました');
      window.showScreen("scr-1778907367889");
    }
  });

  // キャンセル
  container.querySelector('#cancel-btn').addEventListener('click', function() {
    window.showScreen("scr-1778907367889");
  });

  // 初期化
  loadWorkItems();
  loadWorkRecords();
}

