      errorDiv.style.display = 'none';
    }, 5000);
  }

  // 条件バリデーション
  function validateConditions() {
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const outputFormat = container.querySelector('#output-format').value;
    const selectedWorkers = container.querySelectorAll('.worker-checkbox:checked');

    if (!startDate || !endDate) {
      showError('開始日と終了日を入力してください');
      return false;
    }

    if (new Date(startDate) > new Date(endDate)) {
      showError('開始日は終了日より前の日付を入力してください');
      return false;
    }

    if (selectedWorkers.length === 0) {
      showError('作業員を選択してください');
      return false;
    }

    if (!outputFormat) {
      showError('出力形式を選択してください');
      return false;
    }

    return true;
  }

  // 抽出条件取得
  function getExtractionConditions() {
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const workLocation = container.querySelector('#work-location').value;
    const anomalyFilter = container.querySelector('#anomaly-filter').value;
    const interruptionFilter = container.querySelector('#interruption-filter').value;
    const outputFormat = container.querySelector('#output-format').value;

    const selectedWorkers = Array.from(container.querySelectorAll('.worker-checkbox:checked')).map(cb => cb.value);
    const selectedWorkItems = Array.from(container.querySelectorAll('.work-item-checkbox:checked')).map(cb => cb.value);

    return {
      startDate,
      endDate,
      workLocation,
      anomalyFilter,
      interruptionFilter,
      outputFormat,
      selectedWorkers,
      selectedWorkItems
    };
  }

  // データフィルタリング
  function filterData(conditions) {
    let filteredRecords = workRecords.filter(record => {
      const recordDate = new Date(record.作業日 || record.workDate);
      const startDate = new Date(conditions.startDate);
      const endDate = new Date(conditions.endDate);

      // 日付範囲チェック
      if (recordDate < startDate || recordDate > endDate) return false;

      // 作業員チェック
      if (conditions.selectedWorkers.length > 0 && 
          !conditions.selectedWorkers.includes(record.作業員ID || record.workerId)) return false;

      // 作業場所チェック
      if (conditions.workLocation && 
          !(record.作業場所 || record.workLocation || '').includes(conditions.workLocation)) return false;

      return true;
    });

    // 異常値フィルタ
    if (conditions.anomalyFilter === 'exclude') {
      const anomalyRecordIds = anomalies.map(a => a.検出対象レコードID || a.recordId);
      filteredRecords = filteredRecords.filter(r => !anomalyRecordIds.includes(r.作業記録ID || r.id));
    }

    // 中断記録フィルタ
    if (conditions.interruptionFilter === 'exclude') {
      const interruptionRecordIds = interruptions.map(i => i.作業記録ID || i.workRecordId);
      filteredRecords = filteredRecords.filter(r => !interruptionRecordIds.includes(r.作業記録ID || r.id));
    }

    return filteredRecords;
  }

  // プレビュー表示
  function showPreview() {
    const conditions = getExtractionConditions();
    const filteredData = filterData(conditions);

    const previewSection = container.querySelector('#preview-section');
    const conditionPreview = container.querySelector('#condition-preview');
    const dataCount = container.querySelector('#data-count');

    const workerNames = conditions.selectedWorkers.map(id => {
      const user = users.find(u => (u.ユーザーID || u.id) === id);
      return user ? (user.氏名 || user.name) : id;
    }).join(', ');

    const workItemNames = conditions.selectedWorkItems.map(id => {
      const item = workItems.find(i => (i.作業項目ID || i.id) === id);
      return item ? (item.作業項目名 || item.name) : id;
    }).join(', ');

    conditionPreview.innerHTML = `
      <div><strong>期間:</strong> ${conditions.startDate} ～ ${conditions.endDate}</div>
      <div><strong>作業員:</strong> ${workerNames || '全員'}</div>
      <div><strong>作業項目:</strong> ${workItemNames || '全項目'}</div>
      <div><strong>作業場所:</strong> ${conditions.workLocation || '指定なし'}</div>
      <div><strong>異常値:</strong> ${conditions.anomalyFilter === 'include' ? '含む' : '除外'}</div>
      <div><strong>中断記録:</strong> ${conditions.interruptionFilter === 'include' ? '含む' : '除外'}</div>
      <div><strong>出力形式:</strong> ${conditions.outputFormat.toUpperCase()}</div>
    `;

    dataCount.textContent = `抽出データ件数: ${filteredData.length}件`;
    previewSection.style.display = 'block';
  }

  // CSV/Excel出力
  function exportData(conditions, filteredData) {
    const headers = ['作業日', '作業員名', '作業開始時刻', '作業終了時刻', '作業時間', 'プロジェクト名', '作業場所', '作業種別', '作業内容', '進捗状況'];

    const csvData = [headers];
    filteredData.forEach(record => {
      const user = users.find(u => (u.ユーザーID || u.id) === (record.作業員ID || record.workerId));
      const userName = user ? (user.氏名 || user.name) : 'Unknown';

      csvData.push([
        record.作業日 || record.workDate || '',
        userName,
        record.作業開始時刻 || record.startTime || '',
        record.作業終了時刻 || record.endTime || '',
        record.作業時間 || record.workHours || '',
        record.プロジェクト名 || record.projectName || '',
        record.作業場所 || record.workLocation || '',
        record.作業種別 || record.workType || '',
        record.作業内容 || record.workContent || '',
        record.進捗状況 || record.status || ''
      ]);
    });

    const csvContent = '\uFEFF' + csvData.map(row => 
      row.map(field => `"${String(field).replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', `工数記録データ_${new Date().toISOString().split('T')[0]}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  // 条件クリア
  function clearConditions() {
    container.querySelector('#start-date').value = '';
    container.querySelector('#end-date').value = '';
    container.querySelector('#work-location').value = '';
    container.querySelector('#anomaly-filter').value = 'include';
    container.querySelector('#interruption-filter').value = 'include';
    container.querySelector('#output-format').value = '';

    container.querySelectorAll('.worker-checkbox').forEach(cb => cb.checked = false);
    container.querySelectorAll('.work-item-checkbox').forEach(cb => cb.checked = false);
    container.querySelector('#select-all-workers').checked = false;
    container.querySelector('#select-all-items').checked = false;

    container.querySelector('#preview-section').style.display = 'none';
  }

  // 全選択チェックボックス
  container.querySelector('#select-all-workers').addEventListener('change', (e) => {
    container.querySelectorAll('.worker-checkbox').forEach(cb => cb.checked = e.target.checked);
  });

  container.querySelector('#select-all-items').addEventListener('change', (e) => {
    container.querySelectorAll('.work-item-checkbox').forEach(cb => cb.checked = e.target.checked);
  });

  // プレビューボタン
  container.querySelector('#btn-preview').addEventListener('click', () => {
    if (validateConditions()) {
      showPreview();
    }
  });

  // 抽出実行ボタン
  container.querySelector('#btn-extract').addEventListener('click', async () => {
    if (!validateConditions()) return;

    const loadingMessage = container.querySelector('#loading-message');
    loadingMessage.style.display = 'block';

    try {
      const conditions = getExtractionConditions();
      const filteredData = filterData(conditions);

      if (filteredData.length === 0) {
        showError('該当するデータが見つかりませんでした');
        return;
      }

      if (filteredData.length > 10000) {
        showError('抽出データが上限（10,000件）を超えています。条件を絞り込んでください。');
        return;
      }

      // 大量データのタイムアウトシミュレーション
      if (filteredData.length > 5000) {
        await new Promise(resolve => setTimeout(resolve, 31000)); // 31秒待機
        showError('処理がタイムアウトしました。条件を絞り込んでください。');
        return;
      }

      await new Promise(resolve => setTimeout(resolve, 1000)); // 処理時間シミュレーション
      exportData(conditions, filteredData);

    } catch (error) {
      showError('データ抽出中にエラーが発生しました');
    } finally {
      loadingMessage.style.display = 'none';
    }
  });

  // 条件クリアボタン
  container.querySelector('#btn-clear').addEventListener('click', clearConditions);

  // 条件保存ボタン
  container.querySelector('#btn-save-condition').addEventListener('click', () => {
    container.querySelector('#condition-save-modal').style.display = 'block';
  });

  // 条件保存モーダル
  container.querySelector('#btn-cancel-save').addEventListener('click', () => {
    container.querySelector('#condition-save-modal').style.display = 'none';
    container.querySelector('#condition-name').value = '';
  });

  container.querySelector('#btn-confirm-save').addEventListener('click', () => {
    const conditionName = container.querySelector('#condition-name').value;
    if (!conditionName) {
      showError('条件名を入力してください');
      return;
    }

    // 条件保存処理（実際の実装では localStorage等に保存）
    const conditions = getExtractionConditions();
    localStorage.setItem(`extraction_condition_${conditionName}`, JSON.stringify(conditions));

    container.querySelector('#condition-save-modal').style.display = 'none';
    container.querySelector('#condition-name').value = '';

    // 成功メッセージ表示
    const successDiv = document.createElement('div');
    successDiv.textContent = '条件が保存されました';
    successDiv.style.cssText = 'position: fixed; top: 20px; right: 20px; background: var(--primary); color: #fff; padding: 8px 16px; border-radius: 6px; font-size: 13px; z-index: 1001;';
    document.body.appendChild(successDiv);
    setTimeout(() => document.body.removeChild(successDiv), 3000);
  });

  // 戻るボタン
  container.querySelector('#btn-back').addEventListener('click', () => {
    window.showScreen("scr-1778907145716");
  });

  // ホバー効果
  container.querySelector('#btn-extract').addEventListener('mouseenter', (e) => {
    e.target.style.background = 'var(--primary-hover)';
  });
  container.querySelector('#btn-extract').addEventListener('mouseleave', (e) => {
    e.target.style.background = 'var(--primary)';
  });

  const secondaryButtons = container.querySelectorAll('button[style*="transparent"]');
  secondaryButtons.forEach(btn => {
    btn.addEventListener('mouseenter', (e) => {
      e.target.style.background = 'rgba(255,255,255,0.05)';
    });
    btn.addEventListener('mouseleave', (e) => {
      e.target.style.background = 'transparent';
    });
  });

  // 初期データ読み込み
  loadInitialData();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector('#records-tbody');
  const emptyMessage = container.querySelector('#empty-message');
  const detailModal = container.querySelector('#detail-modal');
  const deleteModal = container.querySelector('#delete-modal');
  const approveModal = container.querySelector('#approve-modal');

  let currentRecords = [];
  let deleteTargetId = null;
  let approveTargetId = null;

  // 異常値検出関数
  function detectAnomalies(record) {
    const anomalies = [];

    if (record.作業時間 && record.作業時間 > 1440) { // 24時間 = 1440分
      anomalies.push('24時間超過');
    }

    if (record.作業開始時刻 && record.作業終了時刻) {
      const start = new Date(`2000-01-01 ${record.作業開始時刻}`);
      const end = new Date(`2000-01-01 ${record.作業終了時刻}`);
      if (end < start) {
        anomalies.push('終了時刻が開始時刻より早い');
      }
    }

    // 中断時間の合計を計算
    window.aivicApi.list(2).then(interruptions => {
      const recordInterruptions = interruptions.filter(i => i.作業記録ID === record.作業記録ID);
      const totalInterruptionTime = recordInterruptions.reduce((sum, i) => sum + (i.中断時間 || 0), 0);

      if (totalInterruptionTime > record.作業時間) {
        anomalies.push('中断時間が実働時間を超過');
      }
    });

    return anomalies;
  }

  // 時間フォーマット関数
  function formatTime(minutes) {
    if (!minutes) return '-';
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return `${hours}時間${mins}分`;
  }

  // 時刻フォーマット関数
  function formatTimeString(timeStr) {
    if (!timeStr) return '-';
    return timeStr.substring(0, 5); // HH:MM形式
  }

  // 日付フォーマット関数
  function formatDate(dateStr) {
    if (!dateStr) return '-';
    return new Date(dateStr).toLocaleDateString('ja-JP');
  }

  // 作業者名取得関数
  function getWorkerName(workerId) {
    const users = tables[0]?.records || [];
    const user = users.find(u => u.ユーザーID === workerId);
    return user ? user.氏名 : '不明';
  }

  // 中断時間合計取得関数
  async function getTotalInterruptionTime(recordId) {
    try {
      const interruptions = await window.aivicApi.list(2);
      const recordInterruptions = interruptions.filter(i => i.作業記録ID === recordId);
      return recordInterruptions.reduce((sum, i) => sum + (i.中断時間 || 0), 0);
    } catch {
      return 0;
    }
  }

  // テーブル再描画関数
  async function renderRows(rows) {
    currentRecords = rows || [];

    if (currentRecords.length === 0) {
      tbody.innerHTML = '';
      emptyMessage.classList.remove('hidden');
      return;
    }

    emptyMessage.classList.add('hidden');

    const rowsHtml = await Promise.all(currentRecords.map(async (record) => {
      const anomalies = detectAnomalies(record);
      const warningIcon = anomalies.length > 0 ? 
        `<span style="color: #ff6a00; margin-left: 4px;" title="${anomalies.join(', ')}">⚠️</span>` : '';

      const totalInterruptionTime = await getTotalInterruptionTime(record.作業記録ID);
      const workerName = getWorkerName(record.作業員ID);

      // 権限チェック（簡易版）
      const canEdit = record.承認状態 !== '承認済み';
      const canApprove = record.承認状態 === '未承認';
      const canDelete = record.承認状態 !== '承認済み';

      return `
        <tr data-id="${record.作業記録ID}">
          <td>${formatDate(record.作業日)}${warningIcon}</td>
          <td>${workerName}</td>
          <td>${formatTimeString(record.作業開始時刻)}</td>
          <td>${formatTimeString(record.作業終了時刻)}</td>
          <td>${formatTime(record.作業時間)}</td>
          <td>${formatTime(totalInterruptionTime)}</td>
          <td>${formatTime((record.作業時間 || 0) - totalInterruptionTime)}</td>
          <td style="max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${record.作業内容 || ''}">${record.作業内容 || '-'}</td>
          <td>
            <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; 
              ${record.承認状態 === '承認済み' ? 'background: rgba(40, 167, 69, 0.2); color: #28a745;' : 
                record.承認状態 === '差し戻し' ? 'background: rgba(220, 53, 69, 0.2); color: #dc3545;' : 
                'background: rgba(255, 193, 7, 0.2); color: #ffc107;'}">
              ${record.承認状態 || '未承認'}
            </span>
          </td>
          <td>
            <div style="display: flex; gap: 4px; flex-wrap: wrap;">
              <button class="action-btn secondary detail-btn" data-id="${record.作業記録ID}" data-testid="detail-button" style="font-size: 11px; padding: 4px 8px;">詳細</button>
              ${canEdit ? `<button class="action-btn secondary edit-btn" data-id="${record.作業記録ID}" style="font-size: 11px; padding: 4px 8px;">修正</button>` : ''}
              ${canApprove ? `<button class="action-btn approve-btn" data-id="${record.作業記録ID}" style="font-size: 11px; padding: 4px 8px;">承認</button>` : ''}
              ${canDelete ? `<button class="action-btn secondary delete-btn" data-id="${record.作業記録ID}" style="font-size: 11px; padding: 4px 8px; background: rgba(220, 53, 69, 0.1); color: #dc3545;">削除</button>` : ''}
            </div>
          </td>
        </tr>
      `;
    }));

    tbody.innerHTML = rowsHtml.join('');
  }

  // 詳細表示関数
  async function showDetail(recordId) {
    const record = currentRecords.find(r => r.作業記録ID === recordId);
    if (!record) return;

    const totalInterruptionTime = await getTotalInterruptionTime(recordId);
    const workerName = getWorkerName(record.作業員ID);
    const anomalies = detectAnomalies(record);

    const detailContent = container.querySelector('#detail-content');
    detailContent.innerHTML = `
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px;">
        <div>
          <label style="font-size: 11px; color: var(--text-muted); display: block; margin-bottom: 4px;">作業日</label>
          <div style="font-size: 13px; color: var(--text);">${formatDate(record.作業日)}</div>
        </div>
        <div>
          <label style="font-size: 11px; color: var(--text-muted); display: block; margin-bottom: 4px;">作業者</label>
          <div style="font-size: 13px; color: var(--text);">${workerName}</div>
        </div>
        <div>
          <label style="font-size: 11px; color: var(--text-muted); display: block; margin-bottom: 4px;">開始時刻</label>
          <div style="font-size: 13px; color: var(--text);">${formatTimeString(record.作業開始時刻)}</div>
        </div>
        <div>
          <label style="font-size: 11px; color: var(--text-muted); display: block; margin-bottom: 4px;">終了時刻</label>
          <div style="font-size: 13px; color: var(--text);">${formatTimeString(record.作業終了時刻)}</div>
        </div>
        <div>
          <label style="font-size: 11px; color: var(--text-muted); display: block; margin-bottom: 4px;">実働時間</label>
          <div style="font-size: 13px; color: var(--text);">${formatTime(record.作業時間)}</div>
        </div>
        <div>
          <label style="font-size: 11px; color: var(--text-muted); display: block; margin-bottom: 4px;">中断時間</label>
          <div style="font-size: 13px; color: var(--text);">${formatTime(totalInterruptionTime)}</div>
        </div>
        <div>
          <label style="font-size: 11px; color: var(--text-muted); display: block; margin-bottom: 4px;">プロジェクト名</label>
          <div style="font-size: 13px; color: var(--text);">${record.プロジェクト名 || '-'}</div>
        </div>
        <div>
          <label style="font-size: 11px; color: var(--text-muted); display: block; margin-bottom: 4px;">作業場所</label>
          <div style="font-size: 13px; color: var(--text);">${record.作業場所 || '-'}</div>
        </div>
        <div>
          <label style="font-size: 11px; color: var(--text-muted); display: block; margin-bottom: 4px;">作業種別</label>
          <div style="font-size: 13px; color: var(--text);">${record.作業種別 || '-'}</div>
        </div>
        <div>
          <label style="font-size: 11px; color: var(--text-muted); display: block; margin-bottom: 4px;">承認状態</label>
          <div style="font-size: 13px; color: var(--text);">${record.承認状態 || '未承認'}</div>
        </div>
      </div>
      <div style="margin-top: 12px;">
        <label style="font-size: 11px; color: var(--text-muted); display: block; margin-bottom: 4px;">作業内容</label>
        <div style="font-size: 13px; color: var(--text); padding: 8px; background: rgba(0,0,0,0.1); border-radius: 4px; white-space: pre-wrap;">${record.作業内容 || '-'}</div>
      </div>
      ${record.備考 ? `
        <div style="margin-top: 12px;">
          <label style="font-size: 11px; color: var(--text-muted); display: block; margin-bottom: 4px;">備考</label>
          <div style="font-size: 13px; color: var(--text); padding: 8px; background: rgba(0,0,0,0.1); border-radius: 4px; white-space: pre-wrap;">${record.備考}</div>
        </div>
      ` : ''}
      ${anomalies.length > 0 ? `
        <div style="margin-top: 12px; padding: 8px; background: rgba(255, 106, 0, 0.1); border-left: 3px solid #ff6a00; border-radius: 4px;">
          <div style="font-size: 11px; color: #ff6a00; font-weight: 600; margin-bottom: 4px;">⚠️ 異常値検出</div>
          <div style="font-size: 12px; color: var(--text);">${anomalies.join('、')}</div>
        </div>
      ` : ''}
    `;

    detailModal.classList.remove('hidden');
  }

  // CSVエクスポート関数
  function exportCSV() {
    if (currentRecords.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    const headers = ['作業日', '作業者', '開始時刻', '終了時刻', '実働時間', '中断時間', '合計工数', 'プロジェクト名', '作業場所', '作業種別', '作業内容', '承認状態'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...currentRecords.map(record => [
        formatDate(record.作業日),
        getWorkerName(record.作業員ID),
        formatTimeString(record.作業開始時刻),
        formatTimeString(record.作業終了時刻),
        formatTime(record.作業時間),
        '', // 中断時間は非同期なのでここでは空
        formatTime(record.作業時間),
        record.プロジェクト名 || '',
        record.作業場所 || '',
        record.作業種別 || '',
        `"${(record.作業内容 || '').replace(/"/g, '""')}"`,
        record.承認状態 || '未承認'
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `工数記録_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 検索・フィルター関数
  async function searchRecords() {
    try {
      const allRecords = await window.aivicApi.list(1);
      let filteredRecords = allRecords;

      const dateFilter = container.querySelector('#filter-date').value;
      const startDateFilter = container.querySelector('#filter-start-date').value;
      const endDateFilter = container.querySelector('#filter-end-date').value;

      // 日付範囲バリデーション
      if (startDateFilter && endDateFilter && new Date(startDateFilter) > new Date(endDateFilter)) {
        alert('開始日は終了日より前の日付を指定してください');
        return;
      }

      if (dateFilter) {
        filteredRecords = filteredRecords.filter(record => {
          const recordDate = new Date(record.作業日).toISOString().split('T')[0];
          return recordDate === dateFilter;
        });
      }

      if (startDateFilter) {
        filteredRecords = filteredRecords.filter(record => {
          const recordDate = new Date(record.作業日).toISOString().split('T')[0];
          return recordDate >= startDateFilter;
        });
      }

      if (endDateFilter) {
        filteredRecords = filteredRecords.filter(record => {
          const recordDate = new Date(record.作業日).toISOString().split('T')[0];
          return recordDate <= endDateFilter;
        });
      }

      await renderRows(filteredRecords);
    } catch (error) {
      console.error('検索エラー:', error);
      alert('検索中にエラーが発生しました');
    }
  }

  // 削除処理
  async function deleteRecord(recordId) {
    try {
      await window.aivicApi.delete(1, recordId);
      await searchRecords(); // 再検索して表示更新
      alert('記録を削除しました');
    } catch (error) {
      console.error('削除エラー:', error);
      alert('削除中にエラーが発生しました');
    }
  }

  // 承認処理
  async function approveRecord(recordId) {
    try {
      await window.aivicApi.update(1, recordId, { 承認状態: '承認済み', 承認日時: new Date().toISOString() });
      await searchRecords(); // 再検索して表示更新
      alert('記録を承認しました');
    } catch (error) {
      console.error('承認エラー:', error);
      alert('承認中にエラーが発生しました');
    }
  }

  // 初期データ読み込み
  window.aivicApi.list(1).then(renderRows).catch(error => {
    console.error('初期データ読み込みエラー:', error);
    renderRows(tables[1]?.records || []);
  });

  // イベントリスナー設定
  container.querySelector('#btn-search').addEventListener('click', searchRecords);
  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  // 詳細モーダル関連
  container.querySelector('#close-detail').addEventListener('click', () => {
    detailModal.classList.add('hidden');
  });

  // 削除モーダル関連
  container.querySelector('#cancel-delete').addEventListener('click', () => {
    deleteModal.classList.add('hidden');
    deleteTargetId = null;
  });

  container.querySelector('#confirm-delete').addEventListener('click', () => {
    if (deleteTargetId) {
      deleteRecord(deleteTargetId);
      deleteModal.classList.add('hidden');
      deleteTargetId = null;
    }
  });

  // 承認モーダル関連
  container.querySelector('#cancel-approve').addEventListener('click', () => {
    approveModal.classList.add('hidden');
    approveTargetId = null;
  });

  container.querySelector('#confirm-approve').addEventListener('click', () => {
    if (approveTargetId) {
      approveRecord(approveTargetId);
      approveModal.classList.add('hidden');
      approveTargetId = null;
    }
  });

  // イベントデリゲーション
  container.addEventListener('click', async (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    const editBtn = e.target.closest('.edit-btn');
    const deleteBtn = e.target.closest('.delete-btn');
    const approveBtn = e.target.closest('.approve-btn');

    if (detailBtn) {
      const recordId = detailBtn.dataset.id;
      await showDetail(recordId);
    }

    if (editBtn) {
      const recordId = editBtn.dataset.id;
      const record = currentRecords.find(r => r.作業記録ID === recordId);

      if (record && record.承認状態 === '承認済み') {
        alert('承認済みの記録は修正できません');
        return;
      }

      window.showScreen("scr-1778907343735");
    }

    if (deleteBtn) {
      const recordId = deleteBtn.dataset.id;
      const record = currentRecords.find(r => r.作業記録ID === recordId);

      if (record && record.承認状態 === '承認済み') {
        alert('承認済みの記録は削除できません');
        return;
      }

      deleteTargetId = recordId;
      deleteModal.classList.remove('hidden');
    }

    if (approveBtn) {
      const recordId = approveBtn.dataset.id;
      approveTargetId = recordId;
      approveModal.classList.remove('hidden');
    }
  });

  // モーダル外クリックで閉じる
  detailModal.addEventListener('click', (e) => {
    if (e.target === detailModal) {
      detailModal.classList.add('hidden');
    }
  });

  deleteModal.addEventListener('click', (e) => {
    if (e.target === deleteModal) {
      deleteModal.classList.add('hidden');
      deleteTargetId = null;
    }
  });

  approveModal.addEventListener('click', (e) => {
    if (e.target === approveModal) {
      approveModal.classList.add('hidden');
      approveTargetId = null;
    }
  });

  // 今日の日付を初期値に設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#filter-date').value = today;

  // 初期検索実行
  setTimeout(searchRecords, 100);
}

function(container, apiUrl, tables) {
  // 現在のユーザー情報を設定
  const currentUser = { name: "田中太郎", id: "user-001" };
  container.querySelector("#worker-name").value = currentUser.name;

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector("#work-date").value = today;

  let totalBreakMinutes = 0;

  // 作業項目マスタを読み込み
  async function loadWorkItems() {
    try {
      const workItems = await window.aivicApi.list(3); // 作業項目マスタ
      const workItemSelect = container.querySelector("#work-item");
      workItemSelect.innerHTML = '<option value="">選択してください</option>';

      if (workItems) {
        workItems.forEach(item => {
          const option = document.createElement('option');
          option.value = item.作業項目名 || item.name || '';
          option.textContent = item.作業項目名 || item.name || '';
          workItemSelect.appendChild(option);
        });
      }
    } catch (error) {
      console.error('作業項目の読み込みに失敗:', error);
    }
  }

  // 工数計算関数
  function calculateWorkHours() {
    const startTime = container.querySelector("#start-time").value;
    const endTime = container.querySelector("#end-time").value;

    if (!startTime || !endTime) {
      container.querySelector("#total-work-time").textContent = "0:00";
      container.querySelector("#net-work-time").textContent = "0:00";
      container.querySelector("#work-hours").textContent = "0.0h";
      return;
    }

    const start = new Date(`2000-01-01T${startTime}`);
    const end = new Date(`2000-01-01T${endTime}`);

    if (end <= start) {
      showError("開始時刻が終了時刻より後になっています");
      return;
    }

    const totalMinutes = (end - start) / (1000 * 60);
    const netMinutes = Math.max(0, totalMinutes - totalBreakMinutes);

    if (totalMinutes > 24 * 60) {
      showError("24時間以上の作業時間は入力できません");
      return;
    }

    if (totalBreakMinutes > totalMinutes) {
      showError("中断時間は作業時間を超過できません");
      return;
    }

    const totalHours = Math.floor(totalMinutes / 60);
    const totalMins = totalMinutes % 60;
    const netHours = Math.floor(netMinutes / 60);
    const netMins = netMinutes % 60;

    container.querySelector("#total-work-time").textContent = `${totalHours}:${String(totalMins).padStart(2, '0')}`;
    container.querySelector("#net-work-time").textContent = `${netHours}:${String(netMins).padStart(2, '0')}`;
    container.querySelector("#work-hours").textContent = `${(netMinutes / 60).toFixed(1)}h`;

    clearErrors();
  }

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector("#error-messages");
    errorDiv.innerHTML = `<div style="background: rgba(220, 38, 38, 0.1); border: 1px solid rgba(220, 38, 38, 0.3); border-radius: 6px; padding: 8px; color: #fca5a5; font-size: 12px;">${message}</div>`;
  }

  function clearErrors() {
    container.querySelector("#error-messages").innerHTML = "";
  }

  // バリデーション関数
  function validateForm() {
    const workDate = container.querySelector("#work-date").value;
    const startTime = container.querySelector("#start-time").value;
    const endTime = container.querySelector("#end-time").value;
    const workDetails = container.querySelector("#work-details").value;
    const projectName = container.querySelector("#project-name").value;
    const workLocation = container.querySelector("#work-location").value;
    const workType = container.querySelector("#work-type").value;

    if (!workDate || !startTime || !workDetails || !projectName || !workLocation || !workType) {
      showError("必須項目が入力されていません");
      return false;
    }

    // 未来日付チェック
    const selectedDate = new Date(workDate);
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    if (selectedDate > today) {
      showError("未来日付は選択できません");
      return false;
    }

    // 時刻チェック
    if (endTime) {
      const start = new Date(`2000-01-01T${startTime}`);
      const end = new Date(`2000-01-01T${endTime}`);

      if (end <= start) {
        showError("開始時刻が終了時刻より後になっています");
        return false;
      }

      const totalMinutes = (end - start) / (1000 * 60);
      if (totalMinutes > 24 * 60) {
        showError("24時間以上の作業時間は入力できません");
        return false;
      }

      if (totalBreakMinutes > totalMinutes) {
        showError("中断時間は作業時間を超過できません");
        return false;
      }
    }

    return true;
  }

  // フォームクリア関数
  function clearForm() {
    container.querySelector("#work-date").value = today;
    container.querySelector("#project-name").value = "";
    container.querySelector("#work-item").value = "";
    container.querySelector("#work-location").value = "";
    container.querySelector("#work-type").value = "";
    container.querySelector("#start-time").value = "";
    container.querySelector("#end-time").value = "";
    container.querySelector("#break-minutes").value = "";
    container.querySelector("#work-details").value = "";
    totalBreakMinutes = 0;
    container.querySelector("#total-break-time").textContent = "合計: 0分";
    container.querySelector("#total-break-display").textContent = "0:00";
    container.querySelector("#char-count").textContent = "0";
    calculateWorkHours();
    clearErrors();
  }

  // 初期化
  loadWorkItems();

  // イベントリスナー
  container.querySelector("#start-time").addEventListener("change", calculateWorkHours);
  container.querySelector("#end-time").addEventListener("change", calculateWorkHours);

  // 中断時間追加
  container.querySelector("#add-break-btn").addEventListener("click", () => {
    const breakMinutes = parseInt(container.querySelector("#break-minutes").value) || 0;
    if (breakMinutes > 0) {
      totalBreakMinutes += breakMinutes;
      container.querySelector("#total-break-time").textContent = `合計: ${totalBreakMinutes}分`;
      const breakHours = Math.floor(totalBreakMinutes / 60);
      const breakMins = totalBreakMinutes % 60;
      container.querySelector("#total-break-display").textContent = `${breakHours}:${String(breakMins).padStart(2, '0')}`;
      container.querySelector("#break-minutes").value = "";
      calculateWorkHours();
    }
  });

  // 文字数カウント
  container.querySelector("#work-details").addEventListener("input", (e) => {
    const count = e.target.value.length;
    container.querySelector("#char-count").textContent = count;
    if (count > 1000) {
      showError("作業内容詳細は1000文字以内で入力してください");
    } else {
      clearErrors();
    }
  });

  // キャンセルボタン
  container.querySelector("#cancel-btn").addEventListener("click", () => {
    if (confirm("入力内容をクリアしますか？")) {
      clearForm();
    }
  });

  // 一時保存ボタン
  container.querySelector("#temp-save-btn").addEventListener("click", async () => {
    if (!validateForm()) return;

    const formData = {
      作業員ID: currentUser.id,
      作業日: container.querySelector("#work-date").value,
      作業開始時刻: `${container.querySelector("#work-date").value}T${container.querySelector("#start-time").value}`,
      作業終了時刻: container.querySelector("#end-time").value ? `${container.querySelector("#work-date").value}T${container.querySelector("#end-time").value}` : null,
      作業時間: container.querySelector("#end-time").value ? parseInt(container.querySelector("#net-work-time").textContent.split(':')[0]) * 60 + parseInt(container.querySelector("#net-work-time").textContent.split(':')[1]) : null,
      プロジェクト名: container.querySelector("#project-name").value,
      作業場所: container.querySelector("#work-location").value,
      作業種別: container.querySelector("#work-type").value,
      作業内容: container.querySelector("#work-details").value,
      進捗状況: "作業中",
      承認状態: "未承認",
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      作成者ID: currentUser.id
    };

    try {
      const result = await window.aivicApi.save(1, formData); // 作業記録テーブル
      if (result) {
        alert("一時保存が完了しました");
      }
    } catch (error) {
      showError("一時保存に失敗しました");
    }
  });

  // 記録確定ボタン
  container.querySelector("#save-btn").addEventListener("click", async () => {
    if (!validateForm()) return;

    if (!container.querySelector("#end-time").value) {
      showError("記録確定には終了時刻の入力が必要です");
      return;
    }

    if (!confirm("工数記録を確定しますか？")) return;

    const netWorkTime = container.querySelector("#net-work-time").textContent;
    const [hours, minutes] = netWorkTime.split(':').map(Number);
    const totalMinutes = hours * 60 + minutes;

    const formData = {
      作業員ID: currentUser.id,
      作業日: container.querySelector("#work-date").value,
      作業開始時刻: `${container.querySelector("#work-date").value}T${container.querySelector("#start-time").value}`,
      作業終了時刻: `${container.querySelector("#work-date").value}T${container.querySelector("#end-time").value}`,
      作業時間: totalMinutes,
      プロジェクト名: container.querySelector("#project-name").value,
      作業場所: container.querySelector("#work-location").value,
      作業種別: container.querySelector("#work-type").value,
      作業内容: container.querySelector("#work-details").value,
      進捗状況: "完了",
      承認状態: "未承認",
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      作成者ID: currentUser.id
    };

    try {
      const result = await window.aivicApi.save(1, formData); // 作業記録テーブル
      if (result) {
        alert("工数記録が正常に登録されました");
        clearForm();
        // 作業履歴一覧画面に遷移
        window.showScreen("scr-1778907145716");
      }
    } catch (error) {
      showError("工数記録の登録に失敗しました");
    }
  });
}
